window.QB_TKP_B10 = [
{id:"TKP-1441", q:"Anda bertugas di loket perekaman KTP-el Disdukcapil. Di tengah antrean panjang, petugas mengumumkan blanko KTP-el habis dan warga yang sudah antre sejak pagi mulai protes. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menenangkan warga, menjelaskan kondisi dengan jujur, menerbitkan Surat Keterangan (Suket) pengganti KTP-el yang berlaku sah, dan mencatat kontak warga untuk dihubungi saat blanko tersedia", s:5},{t:"Menjelaskan bahwa blanko habis dan meminta warga kembali lagi minggu depan tanpa solusi pengganti", s:4},{t:"Tetap melakukan perekaman data biometrik agar warga tidak perlu antre ulang, meski pencetakan ditunda", s:3},{t:"Menyuruh warga pulang dan menyalahkan keterlambatan pasokan blanko dari pusat", s:2},{t:"Menutup loket lebih awal agar tidak didemo warga", s:1}], ex:"Suket pengganti KTP-el sah digunakan sementara; transparansi plus solusi konkret menjaga kepercayaan publik saat kendala logistik."},
{id:"TKP-1442", q:"Seorang warga lanjut usia yang buta huruf datang untuk perekaman KTP-el. Ia tidak bisa membaca formulir dan tampak malu bertanya. Sikap Anda yang paling tepat adalah ....", opts:[{t:"Membacakan formulir dengan sabar, mengisi bersama-sama sambil menjelaskan setiap bagian, dan memastikan datanya benar sebelum perekaman biometrik", s:5},{t:"Meminta warga tersebut membawa anggota keluarga yang bisa membaca untuk membantunya", s:4},{t:"Mengisi formulirnya sendiri tanpa penjelasan agar cepat selesai", s:3},{t:"Menyuruhnya belajar membaca dulu sebelum mengurus dokumen", s:2},{t:"Mengabaikannya dan melayani warga berikutnya yang lebih cepat", s:1}], ex:"Kelompok rentan berhak atas pendampingan penuh; pelayanan inklusif berarti petugas aktif membantu, bukan melempar ke pihak lain."},
{id:"TKP-1443", q:"Pasangan suami istri datang mengurus akta kelahiran bayinya yang baru lahir tiga hari lalu, tetapi rumah sakit belum mengirim laporan kelahiran. Mereka panik karena butuh akta untuk administrasi. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melayani dengan surat keterangan lahir dari RS/bidan sebagai dasar sementara, menjelaskan alur pelaporan, dan membantu mengoordinasikan kekurangan berkasnya", s:5},{t:"Menolak memproses sampai ada laporan kelahiran resmi dari rumah sakit", s:4},{t:"Menyuruh mereka kembali ke rumah sakit dan mengurus sendiri semuanya", s:3},{t:"Memproses akta tanpa verifikasi kelahiran sama sekali", s:2},{t:"Meminta imbalan agar prosesnya bisa dipercepat tanpa laporan RS", s:1}], ex:"Surat keterangan lahir dari faskes sah sebagai dasar awal; petugas proaktif menjembatani kekurangan berkas, bukan menolak mentah-mentah."},
{id:"TKP-1444", q:"KTP-el seorang warga rusak terbakar sebagian saat rumahnya kebakaran. Ia hanya membawa sisa potongan kartu dan fotokopi KK. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memproses penerbitan KTP-el pengganti dengan verifikasi data di sistem SIAK, tanpa mempersulit warga yang sedang tertimpa musibah", s:5},{t:"Meminta warga mengurus surat keterangan kebakaran dari kelurahan dulu sebagai syarat mutlak", s:4},{t:"Menyuruh warga membuat laporan polisi meski kartunya rusak bukan hilang", s:3},{t:"Menolak karena kartu asli tidak utuh", s:2},{t:"Memanfaatkan situasinya untuk meminta biaya percepatan", s:1}], ex:"Data kependudukan tersimpan di sistem; penerbitan pengganti tidak boleh dipersulit dengan syarat berlapis bagi korban musibah."},
{id:"TKP-1445", q:"Seorang warga ingin pindah domisili antarprovinsi karena diterima kerja. Ia bingung alur Surat Keterangan Pindah Warga Negara Indonesia (SKPWNI) dan takut prosesnya lama. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan alur SKPWNI langkah demi langkah, membantu menyiapkan berkas, dan memastikan datanya terbit di daerah asal sebelum ia berangkat", s:5},{t:"Memberikan brosur alur dan memintanya mengikuti sendiri prosedurnya", s:4},{t:"Menyuruhnya mengurus di daerah tujuan saja tanpa SKPWNI", s:3},{t:"Mengatakan prosesnya memang lama agar ia tidak berharap banyak", s:2},{t:"Menawarkan jasa percepatan dengan biaya tambahan", s:1}], ex:"Kepastian alur dan pendampingan mengurangi kecemasan warga; SKPWNI diterbitkan daerah asal sebelum pindah agar data tidak terputus."},
{id:"TKP-1446", q:"Tim Disdukcapil mobile Anda tiba di desa terpencil. Seorang warga penyandang disabilitas fisik tidak bisa datang ke titik layanan karena akses jalan sulit. Tindakan tim yang paling tepat adalah ....", opts:[{t:"Mendatangi rumah warga tersebut untuk perekaman (jemput bola) karena itulah esensi layanan mobile", s:5},{t:"Meminta keluarga membawanya dengan tandu ke titik layanan", s:4},{t:"Mencatat namanya dan berjanji kembali lain waktu tanpa kepastian", s:3},{t:"Melewatkannya karena keterbatasan waktu kunjungan", s:2},{t:"Menyuruh warga mengurus sendiri ke kantor Disdukcapil kabupaten", s:1}], ex:"Layanan jemput bola wajib menjangkau yang paling sulit bergerak; melewatkan mereka menggagalkan tujuan layanan mobile."},
{id:"TKP-1447", q:"Seorang ibu muda mengurus Kartu Identitas Anak (KIA) untuk balitanya tetapi tidak tahu apa manfaat KIA. Sikap Anda yang paling tepat adalah ....", opts:[{t:"Menerbitkan KIA sekaligus menjelaskan manfaatnya (identitas anak, akses layanan kesehatan/pendidikan, tabungan) dengan ramah", s:5},{t:"Menerbitkan KIA tanpa penjelasan karena antrean panjang", s:4},{t:"Menyuruhnya mencari informasi sendiri di internet", s:3},{t:"Mengatakan KIA tidak terlalu penting sehingga tidak perlu diurus", s:2},{t:"Menolak menerbitkan karena anaknya masih balita", s:1}], ex:"Edukasi adalah bagian pelayanan; warga yang paham manfaat akan tertib administrasi dan kembali memanfaatkan layanan."},
{id:"TKP-1448", q:"Keluarga yang sedang berduka datang mengurus akta kematian, tetapi surat keterangan kematian dari rumah sakit tertinggal. Mereka terlihat sangat terpukul. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menyampaikan belasungkawa, menjelaskan berkas yang kurang dengan empati, dan menawarkan memproses sebagian sambil menunggu surat keterangan menyusul", s:5},{t:"Menolak memproses sampai semua berkas lengkap tanpa pengecualian", s:4},{t:"Menyuruh mereka pulang mengambil berkas dan antre ulang dari awal", s:3},{t:"Memproses akta kematian tanpa verifikasi apa pun karena kasihan", s:2},{t:"Memanfaatkan kedukaan mereka untuk meminta uang pelicin", s:1}], ex:"Empati plus fleksibilitas prosedural yang tetap akuntabel adalah standar melayani keluarga berduka."},
{id:"TKP-1449", q:"Hasil verifikasi menunjukkan seorang warga memiliki NIK ganda akibat perekaman dua kali di daerah berbeda. Ia tidak tahu-menahu dan butuh KTP-el segera untuk melamar kerja. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan masalahnya dengan jujur, memproses penunggalan NIK sesuai prosedur, dan menerbitkan Suket sementara agar urusannya tidak terhambat", s:5},{t:"Menyalahkan warga karena merekam dua kali dan menolak melayani", s:4},{t:"Membiarkan NIK ganda dan menerbitkan KTP-el dari salah satu data", s:3},{t:"Menyuruh warga menyelesaikan sendiri ke dua daerah tanpa panduan", s:2},{t:"Meminta bayaran untuk membereskan NIK gandanya", s:1}], ex:"Penunggalan NIK adalah kewenangan prosedural Disdukcapil; Suket sementara melindungi hak warga selama perbaikan data."},
{id:"TKP-1450", q:"Saat layanan perekaman KTP-el di sebuah SMA, beberapa siswa tampak takut dan malu menjalani perekaman biometrik (foto dan sidik jari). Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mencairkan suasana dengan ramah, menjelaskan prosesnya singkat dan tidak sakit, serta memberi contoh terlebih dahulu", s:5},{t:"Memaksa siswa antre tertib dan menegur yang takut agar cepat selesai", s:4},{t:"Melewati siswa yang takut dan melayani yang berani saja", s:3},{t:"Membatalkan perekaman di sekolah tersebut", s:2},{t:"Mengancam siswa yang menolak akan kesulitan mengurus dokumen", s:1}], ex:"Pendekatan persuasif dan edukatif menghilangkan kecemasan; perekaman massal berhasil bila pesertanya nyaman."},
{id:"TKP-1451", q:"Seorang WNA yang menikah dengan WNI datang menanyakan dokumen kependudukan yang bisa ia miliki sebagai pasangan. Ia tidak fasih berbahasa Indonesia. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan dengan sabar (dibantu penerjemah/rekan yang bisa berbahasa Inggris) tentang KITAP/KITAS dan dokumen yang menjadi haknya sesuai aturan", s:5},{t:"Menyuruhnya bertanya ke kantor imigrasi tanpa penjelasan apa pun", s:4},{t:"Memberikan brosur berbahasa Indonesia saja dan memintanya membaca sendiri", s:3},{t:"Menolak melayani karena ia bukan WNI", s:2},{t:"Memanfaatkan ketidaktahuannya untuk memungut biaya tidak resmi", s:1}], ex:"WNA pasangan WNI punya hak dokumen sesuai aturan; hambatan bahasa diatasi petugas, bukan dijadikan alasan penolakan."},
{id:"TKP-1452", q:"Seorang kakek berusia 82 tahun belum pernah memiliki KTP karena tinggal di pedalaman dan tidak tahu cara mengurus. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mendaftarkannya ke program jemput bola/perekaman keliling dan mendampingi penuh prosesnya hingga dokumen terbit", s:5},{t:"Menyuruh keluarganya membawanya ke kantor Disdukcapil", s:4},{t:"Mencatat datanya dan berjanji menghubungi tanpa tindak lanjut jelas", s:3},{t:"Menganggapnya bukan prioritas karena sudah tua", s:2},{t:"Meminta keluarganya membayar agar diprioritaskan", s:1}], ex:"Negara wajib hadir bagi warga yang tertinggal administrasi; jemput bola adalah instrumennya."},
{id:"TKP-1453", q:"Banjir bandang merendam sebuah kelurahan dan banyak dokumen kependudukan warga rusak/hilang. Warga berdatangan meminta penggantian serentak. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Membuka posko layanan darurat di lokasi bencana dengan prosedur dipermudah (verifikasi via sistem) dan prioritas korban terdampak", s:5},{t:"Tetap melayani normal di kantor dan meminta warga datang seperti biasa", s:4},{t:"Melayani seadanya sambil menunggu instruksi atasan berhari-hari", s:3},{t:"Menolak karena berkas pendukung warga ikut hanyut", s:2},{t:"Menjadikan situasi darurat sebagai alasan memungut biaya cepat", s:1}], ex:"Bencana menuntut respons luar biasa: posko darurat plus verifikasi sistemik memulihkan hak administrasi warga tercepat."},
{id:"TKP-1454", q:"Sistem antrean online Disdukcapil penuh untuk dua minggu ke depan. Seorang warga datang langsung dan marah-marah karena butuh KTP-el mendesak untuk operasi rumah sakit. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Tetap tenang, memverifikasi urgensi medisnya, dan memberikan jalur prioritas kemanusiaan sesuai ketentuan", s:5},{t:"Menyuruhnya tetap mengikuti antrean online tanpa pengecualian", s:4},{t:"Balik memarahinya karena tidak tertib antre", s:3},{t:"Memberinya nomor antrean palsu agar ia pergi", s:2},{t:"Memintanya membayar agar bisa diselipkan", s:1}], ex:"Keadaan darurat medis adalah pengecualian kemanusiaan yang sah; petugas memverifikasi lalu memprioritaskan, bukan kaku pada sistem."},
{id:"TKP-1455", q:"Seorang warga menemukan kesalahan penulisan nama di KK-nya (satu huruf berbeda dengan ijazah). Ia khawatir berakibat pada administrasi lain. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memverifikasi dokumen pendukungnya, memproses perbaikan elemen data sesuai prosedur, dan menjelaskan estimasi selesainya", s:5},{t:"Menyuruhnya ke pengadilan karena mengira semua perbaikan nama harus lewat putusan", s:4},{t:"Mengatakan kesalahan satu huruf tidak masalah dan menyuruhnya pulang", s:3},{t:"Menolak memperbaiki karena data sudah lama tercatat", s:2},{t:"Meminta uang jasa untuk memperbaiki kesalahan tersebut", s:1}], ex:"Perbaikan elemen data non-strategis adalah layanan rutin Disdukcapil; kepastian proses menenangkan warga."},
{id:"TKP-1456", q:"Akta kelahiran seorang warga hilang dan ia membutuhkan kutipan kedua untuk pendaftaran kuliah. Ia hanya membawa fotokopi akta yang hilang. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memproses penerbitan kutipan kedua berdasarkan arsip register di sistem setelah verifikasi identitasnya", s:5},{t:"Menyuruhnya membuat akta kelahiran baru dari awal", s:4},{t:"Menolak karena akta asli tidak ada", s:3},{t:"Menyuruhnya mencari dulu sampai ketemu", s:2},{t:"Menawarkan penerbitan cepat dengan imbalan", s:1}], ex:"Arsip register akta tersimpan di sistem; kutipan kedua adalah hak warga dan diterbitkan ulang tanpa prosedur berbelit."},
{id:"TKP-1457", q:"Seorang warga pindah datang ke kota Anda tetapi KK lamanya hilang dalam perjalanan. Ia butuh segera terdaftar untuk administrasi anaknya sekolah. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memverifikasi datanya via sistem kependudukan nasional, memproses penerbitan KK baru di domisili baru, dan menjelaskan tahapannya", s:5},{t:"Menyuruhnya kembali ke daerah asal untuk mengurus KK pengganti dulu", s:4},{t:"Menolak memproses sampai ada KK lama yang asli", s:3},{t:"Mendaftarkannya tanpa verifikasi data sama sekali", s:2},{t:"Memintanya membayar denda karena menghilangkan KK", s:1}], ex:"Data kependudukan terintegrasi nasional; kehilangan dokumen fisik tidak boleh menghambat hak administrasi warga."},
{id:"TKP-1458", q:"Seorang warga meminta legalisasi fotokopi dokumen kependudukannya untuk melamar pekerjaan. Antrean sedang padat. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melayani legalisasi dengan cepat dan teliti karena prosedurnya singkat, tanpa mengorbankan antrean lain", s:5},{t:"Menyuruhnya datang lagi besok karena antrean padat", s:4},{t:"Melegalisasi tanpa memeriksa keaslian dokumen aslinya", s:3},{t:"Menolak karena legalisasi dianggap bukan layanan prioritas", s:2},{t:"Memungut biaya melebihi ketentuan resmi", s:1}], ex:"Legalisasi adalah layanan cepat yang tetap wajib teliti; efisiensi di loket padat menunjukkan profesionalisme."},
{id:"TKP-1459", q:"Keluarga membawa anggota keluarga dengan gangguan jiwa (ODGJ) untuk perekaman KTP-el. Ia gelisah dan sulit diajak bekerja sama. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Bekerja sama dengan keluarga/pendamping, menciptakan suasana tenang, dan melakukan perekaman dengan sabar menyesuaikan kondisinya", s:5},{t:"Menolak merekam karena dianggap tidak memungkinkan", s:4},{t:"Memaksa perekaman dengan cepat meski ia berontak", s:3},{t:"Menyuruh keluarga membawanya ke rumah sakit dulu", s:2},{t:"Mengabaikannya dan melayani warga lain", s:1}], ex:"ODGJ berhak atas identitas kependudukan; perekaman adaptif bersama pendamping adalah wujud pelayanan inklusif."},
{id:"TKP-1460", q:"Pasangan beda agama menanyakan pencatatan perkawinan mereka di Disdukcapil setelah menikah secara agama masing-masing. Mereka mendapat info simpang siur. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan secara netral dan akurat ketentuan pencatatan perkawinan menurut peraturan yang berlaku beserta syaratnya", s:5},{t:"Menolak menjelaskan dengan alasan sensitif", s:4},{t:"Memberikan jawaban setengah-setengah agar tidak disalahkan", s:3},{t:"Menghakimi pilihan mereka secara pribadi", s:2},{t:"Meminta imbalan untuk mengurus pencatatannya", s:1}], ex:"Petugas wajib netral dan informatif; penjelasan akurat mencegah warga menjadi korban calo akibat info simpang siur."},
{id:"TKP-1461", q:"Seorang bayi lahir di rumah dengan bantuan dukun beranak, tanpa surat keterangan lahir dari fasilitas kesehatan. Orang tuanya ingin membuatkan akta kelahiran. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan alternatif bukti kelahiran yang sah (surat keterangan lahir dari penolong/RT/RW) dan memproses akta sesuai ketentuan", s:5},{t:"Menolak karena tidak ada surat keterangan dari rumah sakit", s:4},{t:"Menyuruh mereka membuat surat keterangan palsu dari bidan", s:3},{t:"Mengatakan anaknya tidak bisa memiliki akta kelahiran", s:2},{t:"Meminta biaya besar karena kasusnya sulit", s:1}], ex:"Kelahiran di luar faskes tetap bisa dicatat dengan bukti alternatif yang sah; anak tidak boleh kehilangan hak identitas."},
{id:"TKP-1462", q:"Seorang perantau ingin KTP-el diterbitkan di kota tempatnya bekerja tanpa harus pulang kampung. Ia ragu apakah bisa. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan bahwa perekaman dan penerbitan KTP-el bisa dilakukan di domisili saat ini (tidak harus pulang), lalu membantu prosesnya", s:5},{t:"Menyuruhnya pulang kampung karena data asalnya di sana", s:4},{t:"Memberi jawaban ragu-ragu dan menyuruhnya bertanya ke daerah asal", s:3},{t:"Menolak karena bukan warga asli kota tersebut", s:2},{t:"Menawarkan menguruskan dengan tarif khusus perantau", s:1}], ex:"Prinsip layanan adminduk: perekaman bisa di mana saja; petugas wajib menyampaikan kemudahan ini secara proaktif."},
{id:"TKP-1463", q:"Seorang warga berusia 60 tahun bingung menggunakan aplikasi Identitas Kependudukan Digital (IKD) di ponselnya dan datang ke loket meminta bantuan. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Membantunya mengaktivasi IKD langkah demi langkah dengan sabar hingga ia bisa menggunakannya sendiri", s:5},{t:"Menyuruhnya meminta bantuan anaknya di rumah", s:4},{t:"Mengatakan IKD tidak wajib sehingga tidak perlu diurus", s:3},{t:"Mengaktivasinya asal-asalan tanpa penjelasan", s:2},{t:"Meminta pulsa sebagai imbalan bantuan", s:1}], ex:"Transformasi digital berhasil bila petugas mendampingi warga gaptek, bukan melempar tanggung jawab."},
{id:"TKP-1464", q:"Tim layanan keliling Anda tiba di pulau kecil terluar, tetapi jaringan internet untuk verifikasi sistem sangat lemah. Puluhan warga sudah menunggu. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melakukan perekaman offline/manual terverifikasi, mencatat rapi, dan menyinkronkan data saat jaringan tersedia dengan penjelasan ke warga", s:5},{t:"Membatalkan layanan dan pulang karena tidak ada jaringan", s:4},{t:"Menyuruh warga menunggu sampai jaringan pulih tanpa kepastian waktu", s:3},{t:"Mencatat data seadanya tanpa verifikasi", s:2},{t:"Memungut biaya transportasi tambahan dari warga", s:1}], ex:"Keterbatasan infrastruktur diatasi dengan prosedur offline yang akuntabel; warga pulau terluar tetap terlayani."},
{id:"TKP-1465", q:"Keluarga melaporkan anggota keluarganya meninggal dunia saat bekerja di luar negeri dan membutuhkan akta kematian. Dokumen dari negara tersebut berbahasa asing. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan syarat dokumen (termasuk terjemahan tersumpah bila diperlukan), membantu memverifikasi, dan memproses pencatatan kematiannya", s:5},{t:"Menolak karena kematian terjadi di luar negeri", s:4},{t:"Menyuruh keluarga mengurus sendiri ke kedutaan tanpa panduan", s:3},{t:"Mencatat kematian tanpa dokumen pendukung apa pun", s:2},{t:"Meminta biaya ekstra karena dokumen berbahasa asing", s:1}], ex:"Kematian WNI di luar negeri tetap wajib dicatat; petugas memandu pemenuhan syarat, bukan menolak."},
{id:"TKP-1466", q:"Seorang ibu ingin membuatkan akta kelahiran untuk anaknya dari perkawinan siri (tidak tercatat). Ia takut ditolak dan dipermalukan. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melayani dengan ramah tanpa menghakimi, menjelaskan pencatatan kelahiran anak sesuai ketentuan (nama ibu), dan menjaga kerahasiaan", s:5},{t:"Menolak karena perkawinannya tidak tercatat", s:4},{t:"Mempermalukannya di depan warga lain", s:3},{t:"Mencatat nama ayah tanpa dasar hukum yang sah", s:2},{t:"Meminta imbalan karena kasusnya sensitif", s:1}], ex:"Anak berhak atas akta kelahiran apa pun status perkawinan orang tuanya; pelayanan non-diskriminatif dan menjaga martabat."},
{id:"TKP-1467", q:"Pasangan suami istri yang mengadopsi anak secara resmi menanyakan pencatatan pengangkatan anak di akta kelahiran. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan syarat penetapan pengadilan dan memproses pencatatan pengangkatan anak sesuai peraturan", s:5},{t:"Menyuruh mereka langsung mengganti nama orang tua di akta tanpa prosedur", s:4},{t:"Menolak dengan alasan rumit", s:3},{t:"Memproses tanpa penetapan pengadilan", s:2},{t:"Meminta uang jasa karena prosesnya panjang", s:1}], ex:"Pengangkatan anak sah lewat penetapan pengadilan; petugas memastikan prosedurnya benar demi kepastian hukum anak."},
{id:"TKP-1468", q:"Seorang warga ingin mengganti namanya secara resmi karena nama lamanya sering menjadi bahan ejekan. Ia sudah membawa penetapan pengadilan. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memproses perubahan nama pada dokumen kependudukan berdasarkan penetapan pengadilan dengan ramah dan tanpa menghakimi", s:5},{t:"Menertawakan alasan penggantian namanya", s:4},{t:"Menyuruhnya berpikir ulang dan pulang", s:3},{t:"Memproses tanpa penetapan pengadilan", s:2},{t:"Mempersulit dengan syarat tambahan di luar ketentuan", s:1}], ex:"Perubahan nama dengan penetapan pengadilan adalah hak warga; petugas melayani profesional tanpa menghakimi motif pribadi."},
{id:"TKP-1469", q:"Seorang warga komplain karena pengurusan KK-nya sudah 20 hari belum selesai, padahal ia dijanjikan 14 hari. Ia emosi di loket. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Meminta maaf, menelusuri kendalanya di sistem, memberikan penjelasan jujur dan kepastian waktu penyelesaian", s:5},{t:"Menyalahkan bagian lain dan menyuruhnya menunggu tanpa kepastian", s:4},{t:"Balik membentaknya karena emosi di loket", s:3},{t:"Berjanji palsu akan selesai hari ini juga", s:2},{t:"Mengabaikan komplainnya", s:1}], ex:"Komplain dijawab dengan empati, penelusuran nyata, dan kepastian; menyalahkan pihak lain merusak kepercayaan."},
{id:"TKP-1470", q:"Lima menit sebelum jam layanan tutup, seorang warga tergesa-gesa datang meminta surat keterangan domisili untuk melamar pekerjaan dengan batas akhir hari ini. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Tetap melayaninya karena prosedurnya singkat dan kebutuhannya mendesak dan sah", s:5},{t:"Menyuruhnya datang besok karena loket hampir tutup", s:4},{t:"Melayaninya sambil mengomel tentang kedatangannya yang mepet", s:3},{t:"Menolak dengan alasan sistem sudah dimatikan", s:2},{t:"Melayaninya tetapi meminta uang lembur", s:1}], ex:"Pelayanan publik tidak berhenti tepat di jam tutup bila masih bisa diselesaikan; kebutuhan mendesak warga didahulukan secara wajar."},
{id:"TKP-1471", q:"Tim Anda membuka layanan adminduk keliling di area pasar tradisional. Para pedagang sibuk dan hanya punya waktu istirahat siang sebentar. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menyesuaikan jam layanan dengan waktu istirahat pedagang dan melayani seefisien mungkin tanpa mengurangi ketelitian", s:5},{t:"Tetap pada jam standar dan menyuruh pedagang meninggalkan dagangannya", s:4},{t:"Melayani seadanya agar cepat selesai", s:3},{t:"Membatalkan layanan karena pedagang tidak kooperatif", s:2},{t:"Memungut biaya layanan keliling dari pedagang", s:1}], ex:"Layanan keliling harus adaptif pada ritme warga sasaran; fleksibilitas jam menunjukkan orientasi pelayanan."},
{id:"TKP-1472", q:"Verifikasi data menunjukkan seorang warga tercatat merekam KTP-el dua kali dengan data berbeda. Ia mengaku tidak ingat pernah merekam sebelumnya. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melakukan investigasi data dengan teliti, menggabungkan ke satu NIK yang valid, dan menjelaskan hasilnya kepada warga", s:5},{t:"Langsung menuduhnya melakukan pemalsuan identitas", s:4},{t:"Menghapus salah satu data secara asal tanpa verifikasi", s:3},{t:"Membiarkan data ganda karena takut salah", s:2},{t:"Meminta bayaran untuk membersihkan datanya", s:1}], ex:"Data ganda diselesaikan lewat verifikasi cermat, bukan tuduhan; satu NIK valid melindungi warga dari masalah hukum."},
{id:"TKP-1473", q:"Seorang warga datang tanpa surat pengantar RT/RW untuk mengurus KK, padahal ia dengar syarat itu sudah tidak diperlukan. Petugas lama memintanya. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan bahwa pengantar RT/RW memang sudah tidak disyaratkan, dan memproses layanannya langsung", s:5},{t:"Tetap memintanya karena sudah kebiasaan", s:4},{t:"Menyuruhnya bertanya ke atasan Anda", s:3},{t:"Menolak melayani tanpa surat pengantar", s:2},{t:"Memintanya membayar agar bisa tanpa pengantar", s:1}], ex:"Petugas wajib mengikuti ketentuan terbaru dan mengedukasi warga; syarat yang sudah dihapus tidak boleh diminta lagi."},
{id:"TKP-1474", q:"Seorang ibu hamil besar antre di loket layanan KK. Ia terlihat kelelahan dan antrean masih panjang. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memberikan jalur prioritas bagi ibu hamil sesuai ketentuan, dengan penjelasan sopan kepada antrean", s:5},{t:"Memberinya kursi tetapi tetap sesuai urutan antrean", s:4},{t:"Menyuruhnya pulang dan datang lagi besok pagi", s:3},{t:"Membiarkannya antre seperti biasa demi keadilan", s:2},{t:"Memintanya membayar untuk prioritas", s:1}], ex:"Kelompok prioritas (ibu hamil, lansia, difabel) dilayani lebih dahulu; itu keadilan substantif, bukan diskriminasi."},
{id:"TKP-1475", q:"Data KK seorang warga tidak sinkron dengan data Dapodik sekolah anaknya sehingga anaknya terancam tidak bisa ikut ujian. Orang tua panik. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Segera memverifikasi dan memperbaiki data kependudukannya, lalu berkoordinasi agar sinkronisasi ke Dapodik dipercepat", s:5},{t:"Menyuruh orang tua mengurus sendiri ke sekolah dan dinas pendidikan", s:4},{t:"Mengatakan itu bukan urusan Disdukcapil", s:3},{t:"Memperbaiki data tanpa verifikasi dokumen", s:2},{t:"Meminta imbalan untuk perbaikan cepat", s:1}], ex:"Kesalahan data berdampak pada hak anak; koordinasi lintas sistem adalah tanggung jawab proaktif petugas."},
{id:"TKP-1476", q:"Seorang tunanetra datang untuk perekaman KTP-el. Ia kesulitan mengikuti arahan posisi foto dan pemindaian sidik jari. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memandunya dengan sabar lewat arahan verbal yang jelas dan sentuhan seperlunya dengan izin, hingga perekaman berhasil", s:5},{t:"Menyuruh keluarganya yang memandu seluruh proses", s:4},{t:"Melakukan perekaman asal-asalan yang penting selesai", s:3},{t:"Menolak karena dianggap tidak bisa direkam", s:2},{t:"Menyuruhnya datang dengan pendamping berbayar", s:1}], ex:"Disabilitas netra bukan halangan perekaman; panduan verbal yang sabar memastikan biometrik terekam akurat."},
{id:"TKP-1477", q:"Disdukcapil Anda membuka layanan drive-thru pengambilan dokumen. Seorang warga kebingungan karena ini pertama kalinya. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memandunya dengan ramah lewat pengeras suara/petugas, memastikan identitasnya terverifikasi sebelum dokumen diserahkan", s:5},{t:"Menyuruhnya turun dan antre di loket dalam seperti biasa", s:4},{t:"Menyerahkan dokumen tanpa verifikasi agar cepat", s:3},{t:"Mengusirnya karena menghambat antrean kendaraan", s:2},{t:"Meminta tips karena layanan drive-thru dianggap premium", s:1}], ex:"Inovasi layanan harus inklusif; verifikasi identitas tetap wajib meski lewat drive-thru."},
{id:"TKP-1478", q:"Panti asuhan mengurus akta kelahiran untuk anak asuhnya yang ditelantarkan orang tuanya sejak bayi. Tidak ada data orang tua sama sekali. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memproses pencatatan kelahiran anak berdasarkan ketentuan bagi anak yang tidak diketahui asal-usulnya, berkoordinasi dengan dinas sosial", s:5},{t:"Menolak karena tidak ada data orang tua", s:4},{t:"Menyuruh panti mencari orang tua kandungnya dulu", s:3},{t:"Mengarang data orang tua agar bisa diproses", s:2},{t:"Meminta donasi sebagai syarat pengurusan", s:1}], ex:"Anak telantar berhak atas identitas; ketentuan khusus plus koordinasi dinas sosial menjamin haknya terpenuhi."},
{id:"TKP-1479", q:"Seorang perempuan bercadar menolak difoto tanpa cadar untuk KTP-el dengan alasan keyakinan agama. Ia tetap ingin memiliki KTP-el. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan ketentuan foto KTP-el dengan empati, menawarkan difoto oleh petugas perempuan di ruang tertutup, dan mencari solusi sesuai aturan", s:5},{t:"Memaksanya membuka cadar di depan umum", s:4},{t:"Menolak menerbitkan KTP-el untuknya", s:3},{t:"Menerbitkan KTP-el tanpa foto wajah sama sekali", s:2},{t:"Menyuruhnya memilih antara agama atau KTP", s:1}], ex:"Keyakinan dihormati lewat solusi prosedural (petugas perempuan, ruang tertutup); standar identitas tetap dipenuhi."},
{id:"TKP-1480", q:"NIK seorang balita belum terbit padahal dibutuhkan segera untuk pendaftaran BPJS Kesehatan karena anaknya sakit. Orang tua cemas. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memprioritaskan penerbitan NIK anak tersebut dan berkoordinasi agar datanya segera aktif untuk BPJS", s:5},{t:"Menyuruh orang tua menunggu sesuai antrean normal", s:4},{t:"Mengatakan BPJS bukan urusan Disdukcapil", s:3},{t:"Menerbitkan NIK ganda agar cepat", s:2},{t:"Meminta biaya percepatan penerbitan NIK", s:1}], ex:"Kebutuhan kesehatan anak adalah urgensi kemanusiaan; percepatan prosedural yang sah wajib dilakukan."},
{id:"TKP-1481", q:"Pengungsi korban kebakaran hutan datang ke posko dan ingin pindah domisili sementara ke daerah aman, tetapi semua dokumennya terbakar. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memverifikasi identitasnya via sistem kependudukan dan memproses administrasi perpindahannya dengan prosedur darurat", s:5},{t:"Menolak karena tidak ada dokumen pendukung fisik", s:4},{t:"Menyuruhnya kembali ke daerah asal yang sedang bencana", s:3},{t:"Mencatat data baru tanpa verifikasi sistem", s:2},{t:"Memanfaatkan kondisinya untuk pungutan liar", s:1}], ex:"Korban bencana dilayani dengan prosedur darurat berbasis verifikasi sistem; dokumen fisik yang musnah bukan penghalang."},
{id:"TKP-1482", q:"Seorang lansia tidak bisa menandatangani dokumen karena tangannya gemetar, dan ia malu. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menawarkan alternatif cap jempol yang sah secara hukum dengan penjelasan ramah, tanpa mempermalukannya", s:5},{t:"Memaksanya tetap menandatangani meski tidak terbaca", s:4},{t:"Menyuruh keluarganya memalsukan tanda tangannya", s:3},{t:"Menolak memproses karena tidak ada tanda tangan", s:2},{t:"Menertawakannya di depan warga lain", s:1}], ex:"Cap jempol adalah alternatif sah; pelayanan bermartabat tidak mempermalukan keterbatasan warga."},
{id:"TKP-1483", q:"Seorang warga membutuhkan surat keterangan domisili untuk melamar pekerjaan dengan tenggat hari ini juga. Berkasnya lengkap. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menerbitkan surat keterangan domisili segera karena berkas lengkap dan kebutuhannya sah dan mendesak", s:5},{t:"Menyuruhnya menunggu tiga hari sesuai kebiasaan", s:4},{t:"Menerbitkan tanpa verifikasi domisili yang sebenarnya", s:3},{t:"Menolak karena surat domisili dianggap tidak penting", s:2},{t:"Meminta uang rokok agar cepat diterbitkan", s:1}], ex:"Layanan yang berkasnya lengkap dan prosedurnya singkat wajib diselesaikan cepat, apalagi menyangkut mata pencaharian."},
{id:"TKP-1484", q:"Pasangan yang baru menikah ingin pecah KK dan membuat KK baru. Mereka tidak tahu syaratnya. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan syarat pecah KK (buku nikah/akta perkawinan dan KK lama), membantu menyiapkan, dan memprosesnya", s:5},{t:"Menyuruh mereka membaca sendiri syarat di papan pengumuman", s:4},{t:"Menolak karena KK lama mereka masih berlaku", s:3},{t:"Memproses tanpa akta perkawinan", s:2},{t:"Meminta biaya jasa pecah KK", s:1}], ex:"Edukasi syarat plus pendampingan membuat layanan pecah KK cepat dan benar sejak awal."},
{id:"TKP-1485", q:"Seorang warga protes karena mengira pengurusan KTP-el dikenakan biaya oleh oknum di luar. Ia takut mengurus. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menegaskan bahwa seluruh layanan adminduk GRATIS, memproses layanannya, dan mengajaknya melapor bila menemukan pungutan", s:5},{t:"Mengatakan tidak tahu-menahu soal pungutan di luar", s:4},{t:"Menyuruhnya mengurus lewat calo saja agar cepat", s:3},{t:"Mengabaikan protesnya", s:2},{t:"Ikut memungut biaya karena sudah biasa", s:1}], ex:"Menegaskan gratis plus ajakan melapor pungli adalah perlawanan aktif terhadap calo dan pungutan liar."},
{id:"TKP-1486", q:"Foto KTP-el seorang warga hasilnya buram dan ia meminta perekaman ulang. Petugas sebelumnya enggan mengulang. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melakukan perekaman ulang foto hingga hasilnya layak, karena kualitas biometrik memengaruhi keabsahan dokumen", s:5},{t:"Menyuruh warga menerima saja foto yang buram", s:4},{t:"Menyalahkan petugas sebelumnya di depan warga", s:3},{t:"Menolak dengan alasan sudah direkam sekali", s:2},{t:"Meminta bayaran untuk perekaman ulang", s:1}], ex:"Kualitas hasil adalah tanggung jawab layanan; perekaman ulang demi dokumen yang layak adalah standar mutu."},
{id:"TKP-1487", q:"Orang tua baru melaporkan kelahiran anaknya yang sudah berusia 10 tahun dan belum memiliki akta kelahiran. Ia takut didenda atau dipidana. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menenangkannya, menjelaskan tidak ada denda pidana untuk pelaporan terlambat, dan memproses akta sesuai ketentuan", s:5},{t:"Mengancam akan mendendanya agar jera", s:4},{t:"Menolak karena sudah terlalu lama", s:3},{t:"Menyuruhnya memalsukan tanggal lahir agar terlihat baru", s:2},{t:"Meminta biaya besar karena kasusnya istimewa", s:1}], ex:"Keterlambatan pelaporan bukan kejahatan; menenangkan dan memproses menjamin hak identitas anak terpenuhi."},
{id:"TKP-1488", q:"Hasil foto KTP-el seorang warga selalu gagal karena ia berkeringat berlebihan saat pemindaian sidik jari. Antrean menumpuk. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Dengan sabar membersihkan jarinya, mencoba berulang dengan teknik yang benar, dan memintanya menunggu sebentar dengan penjelasan", s:5},{t:"Menyuruhnya pulang dan datang lain waktu", s:4},{t:"Melewatinya dan melayani warga berikutnya", s:3},{t:"Merekam sidik jari asal-asalan", s:2},{t:"Memarahinya karena menghambat antrean", s:1}], ex:"Kendala teknis biometrik diatasi dengan kesabaran dan teknik, bukan dengan mengorbankan warga atau kualitas data."},
{id:"TKP-1489", q:"Seorang warga difabel kursi roda tidak bisa naik tangga ke lantai dua tempat loket perekaman berada karena lift rusak. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menurunkan layanan ke lantai dasar (perekaman di tempat) agar ia terlayani setara tanpa harus naik", s:5},{t:"Menyuruh keluarganya menggendongnya ke lantai dua", s:4},{t:"Menyuruhnya menunggu sampai lift diperbaiki tanpa kepastian", s:3},{t:"Menolak melayani karena keterbatasan fasilitas", s:2},{t:"Menyuruhnya datang dengan surat kuasa orang lain", s:1}], ex:"Aksesibilitas adalah hak; layanan yang mendatangi warga difabel menjamin kesetaraan."},
{id:"TKP-1490", q:"Seorang warga mengeluh petugas loket sebelah berbicara ketus kepadanya. Ia melapor kepada Anda. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mendengarkan keluhannya dengan empati, meminta maaf atas nama layanan, menindaklanjuti ke atasan/petugas terkait, dan memastikan layanannya tetap diproses baik", s:5},{t:"Membela rekan Anda dan menyalahkan warga yang sensitif", s:4},{t:"Menyuruhnya melapor sendiri ke atasan", s:3},{t:"Mengabaikan laporannya", s:2},{t:"Ikut menceritakan keburukan rekan Anda ke warga", s:1}], ex:"Keluhan ditangani profesional: empati, tindak lanjut internal, dan layanan warga tidak terganggu."},
{id:"TKP-1491", q:"Seorang calo menawarkan Anda uang agar memasukkan berkas warga binaannya ke antrean paling depan setiap hari. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak tegas, melaporkan calo tersebut ke atasan/aparat, dan memastikan antrean berjalan adil", s:5},{t:"Menolak tawarannya tetapi membiarkan calo beroperasi", s:4},{t:"Menerima sesekali karena kasihan pada warga yang dibinanya", s:3},{t:"Menerima tawaran karena menguntungkan", s:2},{t:"Ikut menjadi calo dengan tarif sendiri", s:1}], ex:"Integritas ASN menolak gratifikasi dan aktif memberantas calo demi keadilan antrean."},
{id:"TKP-1492", q:"Atasan Anda meminta agar berkas kepengurusan KTP-el kerabatnya didahulukan meski baru datang, melewati puluhan warga yang antre. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak dengan sopan dan menjelaskan bahwa semua warga dilayani sesuai urutan demi keadilan, lalu menawarkan jalur resmi bila ada urgensi", s:5},{t:"Mematuhi perintah atasan karena takut dimutasi", s:4},{t:"Mendahulukan diam-diam agar tidak ketahuan warga", s:3},{t:"Mendahulukan sambil meminta imbalan dari kerabat atasan", s:1},{t:"Melaporkan atasan ke media sosial tanpa prosedur", s:2}], ex:"Keadilan antrean tidak boleh dikalahkan relasi kuasa; penolakan sopan plus penjelasan adalah integritas. Menyalakan korupsi (imbalan) adalah pelanggaran terberat; pelaporan harus lewat jalur resmi, bukan media sosial."},
{id:"TKP-1493", q:"Anda menemukan rekan kerja menyalahgunakan sisa blanko KTP-el untuk menerbitkan dokumen bagi orang yang tidak berhak. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melaporkan temuan tersebut melalui jalur resmi (atasan/inspektorat/whistleblowing) dengan bukti yang ada", s:5},{t:"Menegurnya secara pribadi tetapi tidak melaporkan", s:4},{t:"Membiarkan karena bukan urusan Anda", s:3},{t:"Ikut memanfaatkannya karena terlihat menguntungkan", s:2},{t:"Memeras rekan tersebut agar berbagi keuntungan", s:1}], ex:"Penyalahgunaan blanko adalah pelanggaran berat; whistleblowing lewat jalur resmi melindungi negara dan data warga."},
{id:"TKP-1494", q:"Seorang warga menyelipkan uang dalam berkasnya agar pengurusan akta kelahirannya dipercepat. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengembalikan uangnya dengan sopan, menjelaskan layanan gratis dan SOP waktu penyelesaian, lalu memproses sesuai antrean", s:5},{t:"Mengambil uangnya tetapi tetap memproses sesuai antrean", s:4},{t:"Mengambil uangnya dan mempercepat layanannya", s:3},{t:"Menolak layanannya karena mencoba menyuap", s:2},{t:"Memintanya menambah uang agar benar-benar cepat", s:1}], ex:"Suap ditolak dan dikembalikan; edukasi tentang layanan gratis memutus budaya pungli."},
{id:"TKP-1495", q:"Menjelang hari raya, seorang warga mengirim parcel mahal ke rumah Anda dengan catatan terima kasih atas bantuan pengurusan dokumennya. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak/mengembalikan parcel tersebut karena termasuk gratifikasi yang wajib ditolak ASN", s:5},{t:"Menerimanya karena dianggap sekadar tanda terima kasih", s:4},{t:"Menerimanya lalu membagikan ke tetangga", s:3},{t:"Menerimanya dan mengharapkan parcel berikutnya", s:2},{t:"Meminta parcel yang lebih besar tahun depan", s:1}], ex:"Gratifikasi terkait jabatan wajib ditolak/dilaporkan; ketegasan menjaga marwah ASN."},
{id:"TKP-1496", q:"Anda diminta membuat laporan fiktif jumlah perekaman KTP-el agar target kinerja dinas tercapai. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak memalsukan data dan melaporkan jumlah sebenarnya, serta menyampaikan kendala riil pencapaian target", s:5},{t:"Membuat laporan fiktif karena perintah atasan", s:4},{t:"Membuat laporan fiktif sebagian agar terlihat baik", s:3},{t:"Membiarkan orang lain yang memalsukan", s:2},{t:"Memalsukan sekaligus meminta imbalan", s:1}], ex:"Integritas data kinerja tidak bisa ditawar; kejujuran plus solusi kendala adalah profesionalisme."},
{id:"TKP-1497", q:"Rekan kerja Anda sering titip absen (datang terlambat tetapi tercatat hadir) dan meminta Anda menutupinya. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak menutupi dan menasihatinya untuk disiplin, serta melaporkan bila berlanjut sesuai aturan", s:5},{t:"Menutupinya sekali-sekali karena kasihan", s:4},{t:"Membiarkan tanpa menegur", s:3},{t:"Ikut titip absen juga", s:2},{t:"Menggunakannya untuk memeras rekan tersebut", s:1}], ex:"Disiplin kehadiran adalah kewajiban; menutupi pelanggaran merusak integritas diri dan institusi."},
{id:"TKP-1498", q:"Kendaraan dinas operasional layanan keliling dipakai rekan Anda untuk keperluan pribadi di akhir pekan. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menegur dan mengingatkannya bahwa BMN hanya untuk dinas, serta melaporkan bila diulangi", s:5},{t:"Membiarkan karena bukan kendaraan tanggung jawab Anda", s:4},{t:"Ikut meminjam untuk keperluan pribadi juga", s:3},{t:"Melaporkannya ke media sosial", s:2},{t:"Meminta ikut memakai sebagai imbalan tutup mulut", s:1}], ex:"Barang milik negara untuk kepentingan dinas; peneguran dan pelaporan prosedural menegakkan aturan."},
{id:"TKP-1499", q:"Saudara kandung Anda menjadi vendor pengadaan perangkat perekaman di dinas tempat Anda bertugas, dan Anda dilibatkan dalam penilaian tender. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menyatakan konflik kepentingan dan mengundurkan diri dari tim penilai tender tersebut", s:5},{t:"Tetap menjadi penilai tetapi berjanji objektif", s:4},{t:"Menjadi penilai dan memenangkan saudara Anda", s:3},{t:"Merahasiakan hubungan keluarga tersebut", s:2},{t:"Meminta komisi dari saudara Anda", s:1}], ex:"Konflik kepentingan diselesaikan dengan mundur dari proses; integritas pengadaan di atas segalanya."},
{id:"TKP-1500", q:"Seorang warga menawarkan imbalan besar agar Anda menerbitkan KTP-el dengan data usia yang dimudakan untuk keperluan melamar kerja. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak tegas karena pemalsuan data kependudukan adalah tindak pidana, dan menjelaskan risikonya", s:5},{t:"Menolak tetapi tidak menjelaskan apa-apa", s:4},{t:"Mempertimbangkan karena kasihan", s:3},{t:"Menerima tawaran tersebut", s:2},{t:"Menerima dan menawarkan jasa serupa ke warga lain", s:1}], ex:"Pemalsuan data kependudukan berimplikasi pidana; penolakan tegas plus edukasi melindungi warga dari masalah hukum."},
{id:"TKP-1501", q:"Oknum di lingkungan kantor meminta 'uang rokok' kepada setiap warga yang mengambil dokumen jadi. Warga takut melapor. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengumpulkan bukti dan melaporkan oknum tersebut ke atasan/inspektorat serta mengedukasi warga untuk tidak membayar", s:5},{t:"Menasihati oknum tersebut secara pribadi tanpa laporan resmi", s:4},{t:"Membiarkan karena sudah menjadi kebiasaan lama", s:3},{t:"Ikut meminta bagian dari hasil pungutan", s:2},{t:"Menjadi perantara pungutan agar terlihat resmi", s:1}], ex:"Pungli diberantas lewat laporan resmi plus edukasi warga; pembiaran sama dengan pembenaran."},
{id:"TKP-1502", q:"Anda mengetahui data kependudukan warga diperjualbelikan oleh oknum untuk kepentingan marketing pinjol. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melaporkan ke atasan dan aparat penegak hukum karena pelanggaran perlindungan data pribadi yang serius", s:5},{t:"Memperingatkan oknumnya saja", s:4},{t:"Membiarkan karena Anda tidak dirugikan", s:3},{t:"Meminta data tersebut untuk kepentingan pribadi", s:2},{t:"Ikut menjual data karena menguntungkan", s:1}], ex:"Jual beli data kependudukan melanggar UU Perlindungan Data Pribadi; pelaporan ke aparat adalah kewajiban."},
{id:"TKP-1503", q:"Menjelang pilkada, tim sukses calon meminta daftar warga beserta NIK di wilayah Anda untuk 'pendataan'. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak tegas karena data kependudukan tidak boleh digunakan untuk kepentingan politik praktis", s:5},{t:"Memberikan data sebagian karena didesak", s:4},{t:"Memberikan dengan imbalan", s:3},{t:"Memberikan karena takut diintimidasi", s:2},{t:"Aktif membantu tim sukses menggunakan data dinas", s:1}], ex:"Netralitas ASN dan kerahasiaan data kependudukan melarang pemberian data untuk politik praktis."},
{id:"TKP-1504", q:"Rekan Anda memanipulasi antrean online dengan memblokir slot untuk dijual ke calo. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melaporkan manipulasi tersebut ke atasan/unit IT agar sistem diperbaiki dan pelakunya ditindak", s:5},{t:"Menegurnya tetapi tidak melaporkan", s:4},{t:"Membiarkan karena sistem memang bermasalah", s:3},{t:"Ikut menjual slot antrean", s:2},{t:"Meminta jatah slot untuk dijual sendiri", s:1}], ex:"Manipulasi sistem layanan publik adalah pelanggaran integritas; laporan resmi melindungi hak warga."},
{id:"TKP-1505", q:"Atasan memerintahkan Anda menandatangani berita acara serah terima blanko KTP-el yang jumlahnya tidak sesuai fisik. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak menandatangani yang tidak sesuai fakta dan meminta penghitungan ulang bersama", s:5},{t:"Menandatangani karena perintah atasan", s:4},{t:"Menandatangani tetapi mencatat keberatan di hati saja", s:3},{t:"Menandatangani dengan imbalan", s:2},{t:"Memalsukan berita acara yang lebih rapi", s:1}], ex:"Tanda tangan adalah pertanggungjawaban hukum; menolak menandatangani yang fiktif adalah integritas."},
{id:"TKP-1506", q:"Seorang warga memohon agar akta kematiannya diterbitkan tanpa surat keterangan kematian karena keluarganya tidak mampu membayar biaya rumah sakit untuk menebus surat tersebut. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan alternatif bukti yang sah, berkoordinasi dengan pihak terkait, dan tidak memungut biaya apa pun dari warga", s:5},{t:"Menolak mentah-mentah karena syarat tidak lengkap", s:4},{t:"Menerbitkan tanpa verifikasi sama sekali", s:3},{t:"Menyuruh warga berutang untuk menebus surat RS", s:2},{t:"Meminta imbalan untuk menerbitkan tanpa syarat", s:1}], ex:"Kemiskinan bukan penghalang hak administrasi; solusi prosedural yang empatik tanpa pungutan."},
{id:"TKP-1507", q:"Anda ditawari menjadi 'konsultan' perusahaan yang sering mengurus dokumen massal di dinas Anda, dengan honor rutin. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak karena berpotensi konflik kepentingan dan gratifikasi terselubung", s:5},{t:"Menerima tetapi berjanji tetap profesional", s:4},{t:"Menerima diam-diam", s:3},{t:"Menerima dan memprioritaskan dokumen perusahaan itu", s:2},{t:"Meminta honor lebih besar", s:1}], ex:"Rangkap peran dengan pihak yang dilayani adalah konflik kepentingan klasik yang wajib ditolak."},
{id:"TKP-1508", q:"Laporan kinerja bulanan seksi Anda jauh di bawah target karena blanko kosong dua minggu. Atasan menyuruh 'mengatur' angkanya. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melaporkan angka riil disertai penjelasan kendala blanko dan usulan percepatan", s:5},{t:"Mengatur angka sesuai perintah", s:4},{t:"Mengatur angka sebagian", s:3},{t:"Menyalin laporan bulan lalu", s:2},{t:"Mengatur angka dan meminta bonus kinerja", s:1}], ex:"Data kinerja jujur plus analisis kendala jauh lebih berguna daripada angka cantik yang fiktif."},
{id:"TKP-1509", q:"Seorang warga lanjut usia memberi Anda amplop berisi uang 'untuk beli kopi' setelah dibantu pengurusan KK. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak dengan halus dan menjelaskan bahwa membantu warga adalah tugas tanpa imbalan", s:5},{t:"Menerima karena nilainya kecil dan tulus", s:4},{t:"Menerima lalu membagikan ke rekan", s:3},{t:"Menerima dan mengharapkan lagi", s:2},{t:"Menolak tetapi memintanya dalam bentuk lain", s:1}], ex:"Pemberian terkait layanan tetap gratifikasi; penolakan halus plus edukasi memutus budaya amplop."},
{id:"TKP-1510", q:"Anda melihat arsip dokumen kependudukan dibuang sembarangan ke tempat sampah umum, berisiko disalahgunakan. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengamankan arsip tersebut, melaporkan ke atasan, dan mengusulkan SOP pemusnahan arsip yang aman", s:5},{t:"Membiarkan karena bukan tugas Anda", s:4},{t:"Mengambil arsip untuk kepentingan pribadi", s:3},{t:"Membakarnya sendiri tanpa berita acara", s:2},{t:"Menjual arsip ke pengepul kertas", s:1}], ex:"Arsip kependudukan mengandung data sensitif; pengamanan plus usulan SOP mencegah penyalahgunaan."},
{id:"TKP-1511", q:"Rekan kerja Anda mengajak Anda ikut grup investasi yang dananya berasal dari 'fee' pengurusan dokumen massal. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan indikasi pungli tersebut ke jalur resmi", s:5},{t:"Menolak ajakannya tetapi tidak melaporkan", s:4},{t:"Ikut berinvestasi karena menguntungkan", s:3},{t:"Ikut dan mengajak rekan lain", s:2},{t:"Meminta jatah lebih besar untuk tutup mulut", s:1}], ex:"'Fee' pengurusan adalah pungli; menolak plus melaporkan memutus mata rantai korupsi."},
{id:"TKP-1512", q:"Warga meminta Anda menerbitkan KK dengan jumlah anggota keluarga yang dimanipulasi agar mendapat bantuan sosial lebih besar. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak karena manipulasi data untuk bansos adalah pelanggaran hukum, dan menjelaskan risikonya", s:5},{t:"Menolak tanpa penjelasan", s:4},{t:"Mempertimbangkan karena kasihan", s:3},{t:"Menerima dengan imbalan", s:2},{t:"Menerima dan menawarkan ke warga lain", s:1}], ex:"Data kependudukan adalah basis bansos; manipulasi merugikan warga lain yang berhak."},
{id:"TKP-1513", q:"Atasan Anda menggunakan stempel dinas untuk melegalisasi dokumen pribadi keluarganya di luar jam kerja tanpa prosedur. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengingatkannya secara sopan bahwa penggunaan stempel dinas harus sesuai prosedur, dan melaporkan bila berlanjut", s:5},{t:"Membiarkan karena ia atasan", s:4},{t:"Ikut meminta dilegalisasikan dokumen pribadi Anda", s:3},{t:"Menyebarkan ke media sosial", s:2},{t:"Menggunakannya untuk kepentingan pribadi Anda juga", s:1}], ex:"Penyalahgunaan wewenang oleh atasan tetap wajib diingatkan dan dilaporkan prosedural, bukan diviralkan."},
{id:"TKP-1514", q:"Seorang pengusaha katering menawarkan kerja sama: setiap acara dinas memakai jasanya, Anda dapat komisi. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak karena komisi dari rekanan adalah gratifikasi/konflik kepentingan", s:5},{t:"Menerima tetapi tetap lewat prosedur", s:4},{t:"Menerima diam-diam", s:3},{t:"Menerima dan memenangkan tendernya", s:2},{t:"Meminta komisi lebih besar", s:1}], ex:"Komisi dari rekanan pengadaan adalah gratifikasi; penolakan menjaga objektivitas pengadaan."},
{id:"TKP-1515", q:"Anda diminta menghapus data riwayat perkawinan seorang pejabat dari sistem agar terlihat belum pernah menikah. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak karena penghapusan data tanpa dasar hukum adalah pelanggaran berat", s:5},{t:"Menolak tetapi tidak melaporkan permintaan tersebut", s:4},{t:"Mempertimbangkan karena yang meminta berpengaruh", s:3},{t:"Menghapus dengan imbalan", s:2},{t:"Menghapus dan menawarkan jasa serupa", s:1}], ex:"Integritas data kependudukan tidak bisa diintervensi kekuasaan; penolakan plus pelaporan melindungi sistem."},
{id:"TKP-1516", q:"Rekan Anda sering pulang lebih awal tetapi meminta Anda meng-cover pekerjaannya tanpa sepengetahuan atasan. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak pola tersebut, menasihatinya disiplin, dan menyampaikan ke atasan bila berlanjut", s:5},{t:"Membantu sesekali karena kasihan", s:4},{t:"Membantu terus agar tim terlihat kompak", s:3},{t:"Ikut pulang lebih awal juga", s:2},{t:"Memerasnya agar mau membantu", s:1}], ex:"Kekompakan tidak berarti menutupi indisipliner; teguran dan pelaporan prosedural menjaga profesionalisme."},
{id:"TKP-1517", q:"Seorang warga mengaku sebagai wartawan dan mengancam akan memviralkan dinas bila permohonannya tidak didahulukan. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Tetap melayani sesuai antrean/prosedur, tidak tunduk pada intimidasi, dan melaporkan ancaman ke atasan", s:5},{t:"Mendahulukannya agar tidak viral", s:4},{t:"Balik mengancamnya", s:3},{t:"Memberinya uang agar tidak memviralkan", s:2},{t:"Menutup layanan karena takut", s:1}], ex:"Intimidasi tidak boleh mengubah prosedur; ketegasan prosedural plus pelaporan adalah respons tepat."},
{id:"TKP-1518", q:"Anda menemukan kesalahan input NIK warga yang menyebabkan ia gagal menerima bansos. Kesalahan dilakukan rekan Anda yang sedang cuti. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Segera memperbaiki data sesuai prosedur, memberitahu warga perkembangannya, dan mencatat untuk evaluasi", s:5},{t:"Menunggu rekan kembali dari cuti", s:4},{t:"Menyalahkan rekan di depan warga", s:3},{t:"Membiarkan karena bukan kesalahan Anda", s:2},{t:"Meminta bayaran untuk perbaikan cepat", s:1}], ex:"Kesalahan berdampak pada hak warga harus segera diperbaiki siapa pun pelakunya; tanpa menyalahkan di depan publik."},
{id:"TKP-1519", q:"Menjelang akhir tahun, atasan meminta Anda mempercepat pengadaan dengan menunjuk langsung rekanan tanpa prosedur yang benar. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak dan menjelaskan pengadaan wajib mengikuti prosedur untuk menghindari masalah hukum", s:5},{t:"Mematuhi karena takut dianggap tidak loyal", s:4},{t:"Mematuhi dengan imbalan", s:3},{t:"Mematuhi lalu cuci tangan", s:2},{t:"Mengusulkan rekanan Anda sendiri", s:1}], ex:"Penunjukan langsung tanpa dasar adalah pelanggaran pengadaan; penolakan berdasar aturan melindungi diri dan institusi."},
{id:"TKP-1520", q:"Seorang warga difabel meminta prioritas layanan tetapi rekan Anda menolak dengan alasan 'semua sama'. Warga mengadu kepada Anda. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan ke rekan bahwa kelompok rentan berhak prioritas sesuai ketentuan, dan memastikan warga terlayani", s:5},{t:"Membela rekan Anda demi solidaritas", s:4},{t:"Menyuruh warga antre seperti biasa", s:3},{t:"Menyalahkan warga yang mengadu", s:2},{t:"Mengabaikan aduan tersebut", s:1}], ex:"Prioritas bagi kelompok rentan adalah ketentuan, bukan pilihan; edukasi internal menegakkan standar layanan."},
{id:"TKP-1521", q:"Anda menerima pesan berisi tawaran memperjualbelikan data NIK warga dari nomor tak dikenal yang mengaku rekan dinas lain. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Tidak menanggapi, menyimpan bukti, dan melaporkan ke atasan/aparat", s:5},{t:"Mengabaikan begitu saja", s:4},{t:"Menanyakan harganya karena penasaran", s:3},{t:"Menerima tawaran tersebut", s:2},{t:"Meneruskan tawaran ke pihak lain", s:1}], ex:"Tawaran jual beli data adalah kejahatan; bukti diamankan dan dilaporkan, bukan diabaikan."},
{id:"TKP-1522", q:"Warga meminta surat keterangan belum menikah untuk keperluan melamar kerja, tetapi data di sistem menunjukkan ia pernah menikah dan bercerai. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak menerbitkan keterangan yang tidak sesuai fakta dan menjelaskan data sebenarnya", s:5},{t:"Menerbitkan sesuai permintaan karena kasihan", s:4},{t:"Menerbitkan dengan imbalan", s:3},{t:"Menghapus riwayat pernikahannya dari sistem", s:2},{t:"Menyuruhnya memalsukan sendiri", s:1}], ex:"Keterangan harus sesuai fakta sistem; menerbitkan yang palsu adalah pemalsuan dokumen."},
{id:"TKP-1523", q:"Rekan kerja Anda ketahuan memfotokopi dokumen kependudukan warga untuk arsip pribadinya. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menegur dan memintanya menghapus/menyerahkan salinan tersebut, serta melaporkan bila menyangkut data sensitif", s:5},{t:"Membiarkan karena hanya fotokopi", s:4},{t:"Ikut meminta salinannya", s:3},{t:"Menyebarkannya ke grup kantor", s:2},{t:"Menggunakannya untuk memeras warga", s:1}], ex:"Dokumen warga tidak boleh menjadi arsip pribadi; peneguran plus pelaporan mencegah penyalahgunaan."},
{id:"TKP-1524", q:"Anda ditugaskan memverifikasi berkas dan menemukan ijazah warga yang diduga palsu sebagai syarat administrasi. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menunda penerbitan, mengonfirmasi ke instansi penerbit, dan melaporkan dugaan pemalsuan sesuai prosedur", s:5},{t:"Meloloskan karena kasihan", s:4},{t:"Meloloskan dengan imbalan", s:3},{t:"Menyita dan memusnahkan sendiri ijazahnya", s:2},{t:"Memeras warga tersebut", s:1}], ex:"Dugaan dokumen palsu diverifikasi ke penerbit dan dilaporkan; petugas bukan hakim jalanan."},
{id:"TKP-1525", q:"Seorang pejabat daerah menelepon meminta Anda 'membantu' mempercepat penerbitan dokumen keluarganya di luar antrean. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak dengan sopan, menjelaskan prosedur antrean berlaku untuk semua, dan menawarkan jalur resmi bila ada urgensi", s:5},{t:"Membantu karena takut karier terhambat", s:4},{t:"Membantu diam-diam", s:3},{t:"Membantu dengan imbalan", s:2},{t:"Menyebarkan rekaman telepon ke publik", s:1}], ex:"Intervensi kekuasaan ditolak sopan dengan penjelasan prosedural; kesetaraan layanan di atas relasi."},
{id:"TKP-1526", q:"Anda melihat tumpukan berkas warga terbengkalai berminggu-minggu karena petugasnya malas. Warga sudah bolak-balik. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melaporkan ke atasan agar berkas segera ditangani dan sistem pengawasan diperbaiki", s:5},{t:"Mengambil alih diam-diam tanpa laporan", s:4},{t:"Membiarkan karena bukan berkas Anda", s:3},{t:"Menyuruh warga menunggu lebih sabar", s:2},{t:"Meminta bayaran warga untuk mengambil alih", s:1}], ex:"Berkas terbengkalai adalah maladministrasi; pelaporan resmi memperbaiki sistem, bukan sekadar menambal."},
{id:"TKP-1527", q:"Seorang warga menawarkan Anda menjadi makelar tanah dengan iming-iming komisi, memanfaatkan akses data kependudukan Anda. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak tegas karena menyalahgunakan akses data jabatan untuk bisnis pribadi", s:5},{t:"Menolak tetapi tetap berteman baik", s:4},{t:"Menerima sebagai sampingan", s:3},{t:"Menerima dan memakai data dinas", s:2},{t:"Aktif menawarkan ke warga lain", s:1}], ex:"Akses data jabatan tidak boleh dimonetisasi; penolakan tegas menjaga batas profesional."},
{id:"TKP-1528", q:"Hasil audit menemukan selisih kas retribusi layanan di seksi Anda (padahal layanan gratis). Bendahara menyalahkan sistem. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mendukung audit transparan, membuka data, dan melaporkan bila ada indikasi pungutan liar", s:5},{t:"Membela bendahara tanpa memeriksa", s:4},{t:"Menutup-nutupi agar seksi tidak malu", s:3},{t:"Ikut menyalahkan sistem", s:2},{t:"Memanfaatkan situasi untuk menjatuhkan bendahara", s:1}], ex:"Selisih kas di layanan gratis mengindikasikan pungli; transparansi audit adalah satu-satunya jalan."},
{id:"TKP-1529", q:"Rekan Anda meminta password akun sistem SIAK Anda karena ia lupa passwordnya dan ada warga mendesak. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak berbagi password dan membantunya melalui prosedur reset resmi agar cepat", s:5},{t:"Memberikan password karena mendesak", s:4},{t:"Memberikan dan memintanya merahasiakan", s:3},{t:"Memberikan dengan imbalan", s:2},{t:"Memberikan password atasan sekalian", s:1}], ex:"Kredensial sistem tidak boleh dibagi apa pun alasannya; reset resmi cepat dan akuntabel."},
{id:"TKP-1530", q:"Seorang warga protes keras karena namanya dicatut orang lain untuk perekaman KTP-el ganda. Ia menuntut pertanggungjawaban dinas. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Meminta maaf, menyelidiki pencatutan datanya, memulihkan data yang benar, dan melaporkannya ke aparat bila ada unsur pidana", s:5},{t:"Menyalahkan warga yang tidak menjaga datanya", s:4},{t:"Mengabaikan protesnya", s:3},{t:"Menghapus data ganda tanpa investigasi", s:2},{t:"Meminta bayaran untuk pemulihan data", s:1}], ex:"Pencatutan identitas ditangani serius: investigasi, pemulihan data, dan jalur hukum bila perlu."},
{id:"TKP-1531", q:"Program percepatan akta kelahiran membutuhkan koordinasi dengan rumah sakit dan puskesmas untuk pelaporan kelahiran. Pihak faskes lambat mengirim laporan. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menginisiasi nota kesepahaman dan alur pelaporan yang jelas, lalu rutin berkoordinasi memantau pengirimannya", s:5},{t:"Menyalahkan faskes di depan warga", s:4},{t:"Menunggu faskes mengirim tanpa tindak lanjut", s:3},{t:"Memproses akta tanpa laporan kelahiran", s:2},{t:"Meminta faskes membayar denda keterlambatan ke Anda", s:1}], ex:"Koordinasi lintas instansi dibangun proaktif lewat kesepakatan dan pemantauan, bukan saling menyalahkan."},
{id:"TKP-1532", q:"Perekaman KTP-el massal di sekolah membutuhkan kerja sama dengan pihak sekolah dan dinas pendidikan, tetapi jadwal selalu bentrok. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Berdiskusi mencari jadwal yang disepakati bersama dan menyusun tim gabungan agar tidak mengganggu belajar", s:5},{t:"Memaksakan jadwal dinas Anda", s:4},{t:"Membatalkan program karena sulit koordinasi", s:3},{t:"Menyalahkan sekolah tidak kooperatif", s:2},{t:"Meminta sekolah membayar biaya koordinasi", s:1}], ex:"Kolaborasi efektif lahir dari musyawarah jadwal dan pembagian peran yang saling menghormati."},
{id:"TKP-1533", q:"Bidang pendaftaran penduduk dan bidang pencatatan sipil di dinas Anda saling lempar tanggung jawab atas berkas warga yang tertunda. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengusulkan rapat koordinasi untuk memetakan alur dan pembagian tugas yang jelas antar-bidang", s:5},{t:"Membela bidang Anda dan menyalahkan bidang lain", s:4},{t:"Membiarkan warga bolak-balik antar-bidang", s:3},{t:"Mengambil alih semua pekerjaan bidang lain", s:2},{t:"Memanfaatkan konflik untuk menjatuhkan kepala bidang lain", s:1}], ex:"Ego sektoral diatasi dengan pemetaan alur bersama; warga tidak boleh jadi korban lempar tanggung jawab."},
{id:"TKP-1534", q:"Desa menolak membantu verifikasi domisili warga dengan alasan bukan tugas mereka. Padahal verifikasi itu mempercepat layanan. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Berkunjung dan berdialog dengan perangkat desa, menjelaskan manfaat bersama, dan menyepakati mekanisme verifikasi yang ringan", s:5},{t:"Melaporkan desa ke bupati agar ditegur", s:4},{t:"Memaksa dengan surat perintah", s:3},{t:"Melewati verifikasi desa begitu saja", s:2},{t:"Menyuap perangkat desa agar mau membantu", s:1}], ex:"Kemitraan dengan desa dibangun lewat dialog dan kemudahan, bukan paksaan birokratis."},
{id:"TKP-1535", q:"Tim layanan keliling Anda terdiri dari petugas berbagai seksi yang belum pernah bekerja sama. Di lapangan terjadi miskomunikasi. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengadakan briefing peran tiap anggota sebelum berangkat dan evaluasi singkat setiap akhir hari", s:5},{t:"Membiarkan masing-masing bekerja sendiri-sendiri", s:4},{t:"Menyalahkan anggota yang salah paham", s:3},{t:"Memimpin dengan otoriter tanpa diskusi", s:2},{t:"Melaporkan tim sebagai tidak kompeten", s:1}], ex:"Tim ad-hoc butuh briefing peran dan evaluasi harian; komunikasi terstruktur mencegah miskomunikasi lapangan."},
{id:"TKP-1536", q:"Kantor Kementerian Agama setempat lambat menerbitkan buku nikah sehingga pencatatan perkawinan di Disdukcapil ikut tertunda. Pasangan pengantin cemas. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Berkoordinasi dengan Kemenag untuk sinkronisasi data dan memberi kepastian jadwal kepada pasangan", s:5},{t:"Menyalahkan Kemenag di depan pasangan", s:4},{t:"Menyuruh pasangan menunggu tanpa kepastian", s:3},{t:"Mencatat perkawinan tanpa buku nikah", s:2},{t:"Meminta pasangan membayar percepatan", s:1}], ex:"Hambatan antar-lembaga diselesaikan lewat koordinasi aktif; warga berhak atas kepastian jadwal."},
{id:"TKP-1537", q:"Rekan satu tim Anda kewalahan menangani tumpukan verifikasi berkas sementara pekerjaan Anda sudah selesai. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menawarkan bantuan mengerjakan sebagian verifikasi setelah memahami standarnya", s:5},{t:"Pulang lebih awal karena tugas Anda selesai", s:4},{t:"Menontoninya bekerja tanpa membantu", s:3},{t:"Melaporkan ia lamban ke atasan", s:2},{t:"Membantu tetapi meminta imbalan", s:1}], ex:"Gotong royong tim berarti membantu rekan yang kewalahan; beban bersama diselesaikan bersama."},
{id:"TKP-1538", q:"Dinas kependudukan pusat meminta data agregat daerah Anda dalam waktu singkat untuk keperluan nasional, tetapi data belum terkonsolidasi. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengoordinasikan tim lembur terstruktur, memvalidasi cepat, dan mengirim data terbaik yang terverifikasi tepat waktu", s:5},{t:"Mengirim data seadanya tanpa validasi", s:4},{t:"Mengabaikan permintaan pusat", s:3},{t:"Memalsukan angka agar terlihat lengkap", s:2},{t:"Menyalahkan daerah lain yang juga lambat", s:1}], ex:"Permintaan nasional dipenuhi lewat kerja tim terstruktur; data yang dikirim tetap harus valid."},
{id:"TKP-1539", q:"Kepolisian meminta verifikasi data kependudukan untuk penyelidikan, tetapi prosedurnya berbelit. Penyidik mendesak. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memproses sesuai prosedur resmi yang dipercepat untuk penegakan hukum, dengan dokumentasi lengkap", s:5},{t:"Memberikan data tanpa prosedur karena mendesak", s:4},{t:"Menolak membantu penegak hukum", s:3},{t:"Memberikan data berlebihan di luar permintaan", s:2},{t:"Meminta imbalan dari penyidik", s:1}], ex:"Dukungan pada penegakan hukum diberikan lewat prosedur resmi yang dipercepat dan terdokumentasi."},
{id:"TKP-1540", q:"BPJS Kesehatan meminta sinkronisasi data NIK agar peserta tidak gagal verifikasi. Data Anda belum sinkron. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Berkolaborasi dengan tim BPJS menjadwalkan sinkronisasi berkala dan menyelesaikan backlog perbaikan data", s:5},{t:"Menyalahkan BPJS yang tidak sinkron", s:4},{t:"Membiarkan warga gagal verifikasi", s:3},{t:"Mengubah data warga agar cocok dengan BPJS", s:2},{t:"Meminta BPJS membayar jasa sinkronisasi", s:1}], ex:"Sinkronisasi lintas sistem butuh kolaborasi terjadwal; data diperbaiki pada sumbernya, bukan dimanipulasi."},
{id:"TKP-1541", q:"Ketua RT protes karena warganya tidak kunjung mendapat KTP-el dan menuduh dinas Anda lamban di grup WhatsApp warga. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menghubungi ketua RT, menjelaskan statusnya dengan data, menindaklanjuti percepatan, dan memulihkan komunikasi", s:5},{t:"Balik memarahi ketua RT di grup", s:4},{t:"Mengabaikan tuduhan tersebut", s:3},{t:"Menyalahkan warga yang tidak mengurus", s:2},{t:"Meminta ketua RT menghapus pesannya dengan imbalan", s:1}], ex:"Kritik publik dijawab dengan data dan tindak lanjut nyata; memulihkan kepercayaan lewat komunikasi langsung."},
{id:"TKP-1542", q:"Dinas sosial membutuhkan data kependudukan untuk penyaluran bansos, tetapi khawatir data disalahgunakan. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Berbagi data sesuai perjanjian kerja sama dengan batasan penggunaan dan perlindungan data yang jelas", s:5},{t:"Menolak berbagi data sama sekali", s:4},{t:"Memberikan seluruh database tanpa batasan", s:3},{t:"Memberikan data dengan imbalan", s:2},{t:"Memberikan data palsu", s:1}], ex:"Berbagi data antar-instansi sah lewat perjanjian yang membatasi penggunaan dan melindungi privasi warga."},
{id:"TKP-1543", q:"Rekan baru Anda belum paham alur penerbitan akta dan sering salah, memperlambat tim. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mentoring dengan sabar: menjelaskan alur, mendampingi beberapa kasus, lalu memantau mandirinya", s:5},{t:"Membiarkannya belajar sendiri", s:4},{t:"Melaporkan ia tidak kompeten", s:3},{t:"Mengambil alih semua tugasnya", s:2},{t:"Mengolok-olok kesalahannya", s:1}], ex:"Mentoring mempercepat kemandirian rekan baru; tim kuat dibangun lewat berbagi pengetahuan."},
{id:"TKP-1544", q:"Pemerintah kecamatan ingin membuka gerai layanan adminduk tetapi tidak tahu standar sarana dan alurnya. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Membantu menyusun standar gerai, melatih petugas kecamatan, dan mendampingi hingga siap beroperasi", s:5},{t:"Menolak karena bukan kewenangan Anda", s:4},{t:"Memberi panduan seadanya tanpa pendampingan", s:3},{t:"Membiarkan kecamatan trial and error sendiri", s:2},{t:"Meminta anggaran khusus untuk bantuan Anda", s:1}], ex:"Perluasan layanan ke kecamatan didukung penuh dengan standar, pelatihan, dan pendampingan."},
{id:"TKP-1545", q:"Dalam rapat koordinasi, usulan Anda ditolak mentah-mentah oleh kepala bidang lain tanpa alasan jelas. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Meminta penjelasan dan data pembanding secara profesional, lalu menyempurnakan usulan bila memang kurang", s:5},{t:"Tersinggung dan mogok berkontribusi", s:4},{t:"Menyerang balik kepala bidang tersebut", s:3},{t:"Melobi atasan untuk memaksakan usulan", s:2},{t:"Menyabotase program bidang lain", s:1}], ex:"Penolakan dihadapi profesional: minta alasan, perbaiki usulan; emosi merusak kolaborasi."},
{id:"TKP-1546", q:"Warga transmigran dari luar pulau kesulitan bahasa dan tidak paham prosedur. Perangkat desa meminta bantuan dinas. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Berkolaborasi dengan perangkat desa dan penerjemah lokal untuk sosialisasi dan pendampingan pengurusan dokumennya", s:5},{t:"Menyuruh mereka belajar bahasa Indonesia dulu", s:4},{t:"Menolak karena keterbatasan bahasa", s:3},{t:"Memproses tanpa memastikan data benar", s:2},{t:"Meminta biaya penerjemah dari warga", s:1}], ex:"Hambatan bahasa diatasi lewat kolaborasi lokal; setiap warga berhak terlayani apa pun bahasanya."},
{id:"TKP-1547", q:"Dinas pendidikan meminta data anak usia sekolah untuk perencanaan, tetapi data Anda belum mutakhir. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Bekerja sama melakukan pemutakhiran data bersama (coklit) lalu berbagi data agregat yang valid", s:5},{t:"Memberikan data lama tanpa keterangan", s:4},{t:"Menolak dengan alasan data belum siap", s:3},{t:"Mengarang data agar terlihat mutakhir", s:2},{t:"Meminta imbalan untuk pemutakhiran", s:1}], ex:"Data bersama dimutakhirkan lewat kerja sama pencocokan; kejujuran kualitas data di atas gengsi."},
{id:"TKP-1548", q:"Tim Anda gagal mencapai target perekaman bulan ini. Dalam evaluasi, anggota saling menyalahkan. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengajak evaluasi objektif berbasis data, mengidentifikasi akar masalah, dan menyusun rencana perbaikan bersama", s:5},{t:"Ikut menyalahkan anggota yang paling lemah", s:4},{t:"Membela diri dan menyalahkan faktor eksternal", s:3},{t:"Memalsukan capaian agar terlihat berhasil", s:2},{t:"Mengundurkan diri dari tim", s:1}], ex:"Evaluasi tim fokus pada akar masalah dan solusi bersama, bukan kambing hitam."},
{id:"TKP-1549", q:"LSM pemerhati disabilitas menawarkan kerja sama layanan adminduk inklusif. Sebagian rekan meremehkan tawaran itu. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mendukung kerja sama, memfasilitasi audiensi, dan menyusun program layanan inklusif bersama", s:5},{t:"Mengikuti rekan yang meremehkan", s:4},{t:"Menolak karena menambah pekerjaan", s:3},{t:"Menerima tetapi tidak menindaklanjuti", s:2},{t:"Meminta LSM membayar untuk kerja sama", s:1}], ex:"Kemitraan dengan LSM disabilitas memperkuat layanan inklusif; meremehkan mitra adalah kesombongan birokrasi."},
{id:"TKP-1550", q:"Dua seksi berebut menangani program Identitas Kependudukan Digital karena dianggap bergengsi. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengusulkan pembagian peran yang jelas berdasarkan tupoksi dan tim kerja gabungan", s:5},{t:"Mendukung seksi Anda memenangkan perebutan", s:4},{t:"Membiarkan konflik berlarut", s:3},{t:"Mengambil alih program untuk seksi Anda", s:2},{t:"Menyabotase seksi pesaing", s:1}], ex:"Program lintas seksi butuh pembagian peran berbasis tupoksi; perebutan gengsi merugikan layanan."},
{id:"TKP-1551", q:"Karang taruna desa menawarkan membantu sosialisasi pentingnya akta kelahiran kepada warga. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menyambut baik, memberikan materi sosialisasi yang akurat, dan melibatkan mereka sebagai duta layanan", s:5},{t:"Menolak karena bukan tugas mereka", s:4},{t:"Menerima tetapi tidak memberi materi", s:3},{t:"Memanfaatkan mereka untuk kepentingan pribadi", s:2},{t:"Mengabaikan tawaran tersebut", s:1}], ex:"Pemberdayaan komunitas sebagai duta layanan memperluas jangkauan sosialisasi secara efektif."},
{id:"TKP-1552", q:"Atasan meminta Anda memimpin tim gabungan lintas dinas untuk percepatan cakupan akta kelahiran. Anggotanya senior-senior yang sulit diatur. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memimpin dengan komunikasi terbuka, menghargai pengalaman mereka, dan membangun kesepakatan kerja", s:5},{t:"Memimpin otoriter agar ditakuti", s:4},{t:"Menolak tugas karena anggotanya sulit", s:3},{t:"Membiarkan tim berjalan tanpa arah", s:2},{t:"Melaporkan anggota yang tidak patuh", s:1}], ex:"Memimpin senior butuh penghargaan pada pengalaman plus kesepakatan kerja; otoriter merusak tim."},
{id:"TKP-1553", q:"Data kependudukan daerah perbatasan perlu disinkronkan dengan daerah tetangga karena banyak warga beraktivitas lintas wilayah. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menginisiasi forum koordinasi rutin antar-Disdukcapil dan mekanisme berbagi data yang disepakati", s:5},{t:"Membiarkan data tumpang tindih", s:4},{t:"Mengklaim warga perbatasan sepihak", s:3},{t:"Menutup akses data ke daerah tetangga", s:2},{t:"Memanfaatkan data ganda untuk kepentingan tertentu", s:1}], ex:"Wilayah perbatasan butuh sinkronisasi proaktif; forum rutin mencegah data ganda dan konflik."},
{id:"TKP-1554", q:"Relawan bencana meminta data jumlah jiwa terdampak untuk distribusi bantuan, waktunya mendesak. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Berkoordinasi cepat memberikan data agregat terdampak sesuai prosedur darurat", s:5},{t:"Menolak karena prosedur normal belum dipenuhi", s:4},{t:"Memberikan data individual lengkap tanpa batasan", s:3},{t:"Menunda sampai situasi normal", s:2},{t:"Meminta imbalan untuk data cepat", s:1}], ex:"Keadaan darurat memungkinkan berbagi data agregat cepat prosedural demi kemanusiaan."},
{id:"TKP-1555", q:"Perusahaan swasta ingin memverifikasi data karyawan lewat kerja sama resmi dengan dinas Anda. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memproses kerja sama resmi dengan perjanjian perlindungan data dan verifikasi terbatas sesuai kebutuhan", s:5},{t:"Menolak semua kerja sama swasta", s:4},{t:"Memberikan akses penuh ke database", s:3},{t:"Memberikan data dengan imbalan pribadi", s:2},{t:"Mengabaikan permohonan tersebut", s:1}], ex:"Verifikasi pihak ketiga sah lewat perjanjian resmi dengan batasan ketat perlindungan data."},
{id:"TKP-1556", q:"Rekan Anda dari dinas lain meminta bantuan mempercepat dokumen keluarganya di luar antrean. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak dengan halus dan menjelaskan semua dilayani sesuai urutan, menawarkan bantuan prosedural yang sah", s:5},{t:"Membantu karena sesama ASN", s:4},{t:"Membantu diam-diam", s:3},{t:"Membantu dengan imbalan", s:2},{t:"Melaporkannya sebagai pelanggaran berat", s:1}], ex:"Solidaritas korps tidak membenarkan jalur khusus; penolakan halus menjaga keadilan layanan."},
{id:"TKP-1557", q:"Mahasiswa KKN menawarkan membantu input data arsip kependudukan yang menumpuk. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menerima dengan pembekalan, pendampingan, dan pembatasan akses data sensitif sesuai aturan", s:5},{t:"Menolak karena takut data bocor", s:4},{t:"Memberi akses penuh tanpa pengawasan", s:3},{t:"Memanfaatkan mereka tanpa pembekalan", s:2},{t:"Meminta mereka membayar untuk pengalaman", s:1}], ex:"Kolaborasi dengan mahasiswa bermanfaat bila dibekali, didampingi, dan dibatasi akses sensitifnya."},
{id:"TKP-1558", q:"Dinas Anda dan dinas kesehatan berbeda data jumlah balita untuk program imunisasi. Masing-masing mengklaim datanya benar. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengusulkan verifikasi bersama ke lapangan dan menyepakati satu data rujukan", s:5},{t:"Bersikeras data dinas Anda yang benar", s:4},{t:"Membiarkan perbedaan berlarut", s:3},{t:"Mengubah data agar sama", s:2},{t:"Menyalahkan dinas kesehatan di publik", s:1}], ex:"Perbedaan data antar-dinas diselesaikan lewat verifikasi bersama; satu data rujukan untuk kebijakan."},
{id:"TKP-1559", q:"Tokoh masyarakat menawarkan aula gratis untuk layanan keliling, tetapi meminta warganya didahulukan. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menerima tawaran aula dengan terima kasih tetapi menjelaskan antrean tetap adil untuk semua warga", s:5},{t:"Menolak tawarannya karena ada syarat", s:4},{t:"Menerima dan mendahulukan warganya", s:3},{t:"Menerima dengan imbalan tambahan", s:2},{t:"Mengabaikan tawaran tersebut", s:1}], ex:"Fasilitas masyarakat dimanfaatkan, tetapi keadilan antrean tidak bisa ditukar dengan fasilitas."},
{id:"TKP-1560", q:"Petugas lapangan Anda kesulitan sinyal saat verifikasi biometrik di daerah pegunungan. Warga sudah menunggu lama. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Berkolaborasi dengan tim: bagi tugas perekaman manual terverifikasi dan sinkronisasi terjadwal, sambil terus berkomunikasi dengan warga", s:5},{t:"Menyuruh tim pulang dan membatalkan layanan", s:4},{t:"Menyalahkan provider sinyal", s:3},{t:"Memalsukan hasil verifikasi", s:2},{t:"Memungut biaya tambahan karena sulit sinyal", s:1}], ex:"Kendala teknis diatasi tim dengan prosedur manual akuntabel; komunikasi menjaga kepercayaan warga menunggu."},
{id:"TKP-1561", q:"Seorang warga suku pedalaman datang dengan nama adat yang sangat panjang dan tidak muat di kolom sistem. Ia tersinggung saat petugas menyingkat seenaknya. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Meminta maaf, menjelaskan keterbatasan kolom, dan menyepakati penulisan yang menghormati nama adatnya sesuai ketentuan", s:5},{t:"Menyingkat seenaknya agar cepat selesai", s:4},{t:"Menyuruhnya mengganti nama yang lebih pendek", s:3},{t:"Menolak melayani karena namanya menyulitkan", s:2},{t:"Menertawakan namanya", s:1}], ex:"Nama adat adalah identitas budaya; penyesuaian teknis dilakukan dengan persetujuan dan penghormatan."},
{id:"TKP-1562", q:"Warga lanjut usia hanya bisa berbahasa daerah dan tidak paham penjelasan petugas tentang syarat akta. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Meminta bantuan rekan/penerjemah lokal yang berbahasa daerah untuk menjelaskan hingga ia paham", s:5},{t:"Berbicara lebih keras dengan bahasa Indonesia", s:4},{t:"Menyuruhnya membawa anaknya sebagai penerjemah", s:3},{t:"Mengabaikannya karena tidak paham", s:2},{t:"Mengusirnya karena menghambat", s:1}], ex:"Hambatan bahasa daerah diatasi dengan penerjemah; berteriak bukan solusi komunikasi."},
{id:"TKP-1563", q:"Seorang perempuan kepala keluarga (janda) merasa dipersulit dan ditanya hal-hal pribadi yang tidak relevan saat mengurus KK. Ia mengadu kepada Anda. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Meminta maaf, memastikan layanannya diproses profesional tanpa pertanyaan tak relevan, dan menegur petugas terkait", s:5},{t:"Membela petugas dan menyalahkan perasaannya", s:4},{t:"Menyuruhnya bersabar saja", s:3},{t:"Mengabaikan aduannya", s:2},{t:"Ikut mempertanyakan statusnya", s:1}], ex:"Perempuan kepala keluarga berhak dilayani setara tanpa stigma; pertanyaan tak relevan adalah pelecehan layanan."},
{id:"TKP-1564", q:"Jadwal layanan keliling berbenturan dengan hari ibadah besar umat tertentu di desa sasaran. Warga meminta penjadwalan ulang. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjadwalkan ulang dengan menghormati hari ibadah dan mengomunikasikan jadwal baru ke semua warga", s:5},{t:"Tetap pada jadwal karena sudah ditetapkan", s:4},{t:"Menyuruh warga memilih layanan atau ibadah", s:3},{t:"Membatalkan layanan ke desa tersebut", s:2},{t:"Mengejek keyakinan mereka", s:1}], ex:"Menghormati hari ibadah dalam penjadwalan adalah toleransi konkret pelayanan publik."},
{id:"TKP-1565", q:"Seorang warga penghayat kepercayaan menanyakan pencatatan kolom kepercayaan di dokumennya dan khawatir didiskriminasi. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan haknya sesuai putusan MK dengan ramah, memproses sesuai ketentuan, dan menjamin kerahasiaan data", s:5},{t:"Menolak dengan alasan sistem belum siap", s:4},{t:"Menyuruhnya memilih salah satu agama resmi", s:3},{t:"Menyebarkan data kepercayaannya", s:2},{t:"Menghakimi keyakinannya", s:1}], ex:"Putusan MK menjamin hak penghayat; pelayanan netral dan rahasia menegakkan keadilan."},
{id:"TKP-1566", q:"Anak dari perkawinan campuran (WNI-WNA) membutuhkan dokumen kependudukan. Orang tuanya bingung status kewarganegaraan anak. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan ketentuan kewarganegaraan ganda terbatas untuk anak dan memproses dokumen sesuai pilihannya yang sah", s:5},{t:"Menyuruh mereka bertanya ke imigrasi tanpa penjelasan", s:4},{t:"Menolak karena statusnya rumit", s:3},{t:"Menetapkan status seenaknya", s:2},{t:"Meminta imbalan untuk mengurus", s:1}], ex:"Anak perkawinan campuran punya hak dokumen jelas; penjelasan akurat mencegah kebingungan berkepanjangan."},
{id:"TKP-1567", q:"Tokoh adat setempat meminta dilibatkan dalam sosialisasi tertib adminduk karena warganya masih banyak yang belum ber-KTP. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menyambut dan melibatkan tokoh adat sebagai mitra sosialisasi karena pengaruhnya besar di komunitas", s:5},{t:"Menolak karena sosialisasi tugas dinas", s:4},{t:"Menerima tetapi tidak menindaklanjuti", s:3},{t:"Memanfaatkan tokoh adat untuk kepentingan pribadi", s:2},{t:"Meremehkan peran tokoh adat", s:1}], ex:"Tokoh adat adalah mitra strategis menjangkau komunitas yang jauh dari negara."},
{id:"TKP-1568", q:"Seorang warga difabel wicara (bisu) kesulitan menyampaikan keperluannya di loket yang bising. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengajaknya ke area yang tenang, berkomunikasi lewat tulisan/gambar dengan sabar hingga keperluannya jelas", s:5},{t:"Menyuruhnya menulis sendiri tanpa bantuan", s:4},{t:"Memanggil satpam untuk mengeluarkannya", s:3},{t:"Mengabaikannya", s:2},{t:"Menertawakannya", s:1}], ex:"Komunikasi alternatif yang sabar memastikan warga difabel wicara terlayani setara."},
{id:"TKP-1569", q:"Warga pendatang dari daerah konflik ingin merahasiakan asal daerahnya karena trauma dan takut stigma. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menghormati privasinya, memproses dokumen sesuai data yang sah, dan tidak menyebarkan latar belakangnya", s:5},{t:"Memaksa menceritakan masa lalunya", s:4},{t:"Menyebarkan asal daerahnya ke warga lain", s:3},{t:"Menolak melayani pendatang", s:2},{t:"Memanfaatkan traumanya untuk imbalan", s:1}], ex:"Privasi dan martabat pengungsi konflik dilindungi; pelayanan fokus pada dokumen, bukan masa lalu."},
{id:"TKP-1570", q:"Seorang ibu muda belum menikah secara resmi ingin mencatatkan kelahiran anaknya tetapi malu pada tetangga yang ikut mengurus di loket yang sama. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melayani di ruang/bilik yang lebih privat bila memungkinkan dan menjaga kerahasiaan data pribadinya", s:5},{t:"Melayani terbuka tanpa memperhatikan rasa malunya", s:4},{t:"Mengumumkan statusnya agar jelas", s:3},{t:"Menolak karena belum menikah resmi", s:2},{t:"Menghakiminya di depan umum", s:1}], ex:"Kerahasiaan dan ruang privat melindungi martabat warga dalam situasi sensitif."},
{id:"TKP-1571", q:"Kelompok warga minoritas agama merasa selalu dilayani terakhir di loket desa. Mereka mengadu kepada Anda. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menyelidiki pola layanan, menegakkan antrean adil, dan memastikan tidak ada diskriminasi", s:5},{t:"Menganggap mereka terlalu sensitif", s:4},{t:"Membela petugas desa tanpa memeriksa", s:3},{t:"Menyuruh mereka mengurus di tempat lain", s:2},{t:"Mengabaikan aduan", s:1}], ex:"Aduan diskriminasi diselidiki serius; keadilan antrean adalah wujud Bhinneka Tunggal Ika."},
{id:"TKP-1572", q:"Seorang warga lanjut usia penganut tradisi lokal meminta namanya ditulis sesuai ejaan tradisi, berbeda dengan ejaan resmi. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan ketentuan penulisan resmi dengan hormat dan mencari titik temu yang tidak mengingkari identitasnya", s:5},{t:"Memaksakan ejaan resmi tanpa penjelasan", s:4},{t:"Menolak melayani", s:3},{t:"Menulis seenaknya", s:2},{t:"Mengejek tradisinya", s:1}], ex:"Dialog hormat menjembatani ketentuan resmi dan identitas tradisi; pemaksaan merusak kepercayaan."},
{id:"TKP-1573", q:"Anak jalanan yang tidak memiliki keluarga ingin dibuatkan identitas agar bisa sekolah. Tidak ada dokumen apa pun. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Berkolaborasi dengan dinas sosial untuk pendataan dan penerbitan identitas sesuai ketentuan anak terlantar", s:5},{t:"Menolak karena tidak ada dokumen", s:4},{t:"Menyuruhnya kembali ke jalanan", s:3},{t:"Mengarang identitasnya", s:2},{t:"Meminta imbalan dari pendampingnya", s:1}], ex:"Anak jalanan berhak atas identitas dan pendidikan; kolaborasi dinas sosial adalah jalurnya."},
{id:"TKP-1574", q:"Warga dari suku yang menjunjung tinggi musyawarah meminta keputusan layanan tidak diambil sepihak oleh petugas muda. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan dengan rendah hati bahwa keputusan mengikuti aturan, sambil tetap mendengar dan menghargai pandangannya", s:5},{t:"Memaksakan keputusan tanpa mendengar", s:4},{t:"Menyerahkan keputusan sepenuhnya padanya", s:3},{t:"Mengabaikan adatnya", s:2},{t:"Meremehkan tradisinya", s:1}], ex:"Ketegasan aturan dipadukan kerendahan hati mendengar; menghargai budaya musyawarah memperkuat legitimasi."},
{id:"TKP-1575", q:"Seorang warga transgender ingin mengganti jenis kelamin di dokumen setelah putusan pengadilan. Petugas lain menolak dengan alasan moral pribadi. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memproses sesuai putusan pengadilan yang sah secara profesional tanpa menghakimi", s:5},{t:"Ikut menolak karena alasan pribadi", s:4},{t:"Menyebarkan kasusnya", s:3},{t:"Mempersulit dengan syarat tambahan", s:2},{t:"Meminta imbalan", s:1}], ex:"Putusan pengadilan wajib dilaksanakan; keyakinan pribadi petugas tidak boleh menghalangi layanan."},
{id:"TKP-1576", q:"Keluarga besar dengan banyak anak merasa malu mengurus akta kelahiran anak-anaknya yang belum tercatat karena takut dianggap tidak mampu. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menyambut baik kesadaran mereka, melayani tanpa menghakimi, dan menjelaskan program yang meringankan", s:5},{t:"Menyindir jumlah anaknya", s:4},{t:"Mempersulit karena terlambat", s:3},{t:"Menolak melayani", s:2},{t:"Meminta bayaran lebih karena banyak anak", s:1}], ex:"Kesadaran tertib administrasi diapresiasi; stigma kemiskinan tidak boleh menghambat hak anak."},
{id:"TKP-1577", q:"Warga pesisir yang mata pencahariannya melaut sulit datang di jam kerja. Mereka meminta layanan di luar jam kerja. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengatur layanan khusus di luar jam kerja/waktu mereka di darat sebagai bentuk afirmasi", s:5},{t:"Menolak karena di luar jam kerja", s:4},{t:"Menyuruh mereka meninggalkan melaut", s:3},{t:"Mengabaikan permintaan", s:2},{t:"Memungut biaya layanan khusus", s:1}], ex:"Afirmasi jadwal bagi kelompok bermata pencaharian khusus adalah keadilan akses layanan."},
{id:"TKP-1578", q:"Seorang nenek mengasuh cucunya karena orang tuanya merantau, dan ingin mengurus dokumen cucunya tetapi bukan wali resmi. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan mekanisme surat kuasa/perwalian yang sah dan membantu menyiapkan syaratnya", s:5},{t:"Menolak mentah-mentah", s:4},{t:"Memproses tanpa dasar perwalian", s:3},{t:"Menyuruhnya menunggu orang tua pulang bertahun-tahun", s:2},{t:"Meminta imbalan", s:1}], ex:"Pengasuhan oleh nenek difasilitasi lewat mekanisme kuasa/perwalian yang sah demi kepentingan anak."},
{id:"TKP-1579", q:"Warga korban KDRT ingin pindah domisili diam-diam agar tidak dilacak pelaku. Ia takut datanya bocor. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memproses perpindahan dengan perlindungan kerahasiaan maksimal dan berkoordinasi dengan layanan perlindungan perempuan bila diperlukan", s:5},{t:"Menolak karena prosedurnya tidak biasa", s:4},{t:"Memberitahu keluarganya tentang kepindahan", s:3},{t:"Menyebarkan datanya", s:2},{t:"Meminta imbalan untuk kerahasiaan", s:1}], ex:"Keselamatan korban KDRT di atas segalanya; kerahasiaan data adalah perlindungan nyata."},
{id:"TKP-1580", q:"Komunitas adat terpencil belum tersentuh layanan adminduk dan curiga pada petugas pemerintah. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Membangun kepercayaan bertahap lewat tokoh adat, sosialisasi yang menghormati, dan layanan jemput bola", s:5},{t:"Memaksa pendataan dengan aparat", s:4},{t:"Membiarkan mereka tanpa identitas", s:3},{t:"Mendata tanpa persetujuan", s:2},{t:"Mengabaikan komunitas tersebut", s:1}], ex:"Kepercayaan komunitas adat dibangun lewat tokoh dan penghormatan, bukan paksaan; hasilnya berkelanjutan."},
{id:"TKP-1581", q:"Seorang ayah ingin mencatatkan anak angkatnya sebagai anak kandung di akta tanpa prosedur adopsi resmi. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak dan menjelaskan prosedur pengangkatan anak yang sah demi kepastian hukum anak", s:5},{t:"Menerima karena kasihan", s:4},{t:"Menerima dengan imbalan", s:3},{t:"Menyarankan memalsukan dokumen", s:2},{t:"Mengabaikan", s:1}], ex:"Pencatatan harus sesuai fakta hukum; prosedur adopsi resmi melindungi hak anak jangka panjang."},
{id:"TKP-1582", q:"Warga lansia penghayat tradisi lokal tidak memiliki dokumen apa pun sejak lahir dan tidak tercatat di mana pun. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memproses pencatatan baru berdasarkan ketentuan bagi penduduk yang belum tercatat, dengan verifikasi saksi dan perangkat desa", s:5},{t:"Menolak karena tidak ada riwayat data", s:4},{t:"Menyuruhnya menerima nasib tanpa identitas", s:3},{t:"Mengarang data kelahirannya", s:2},{t:"Meminta bayaran besar", s:1}], ex:"Setiap penduduk berhak tercatat; mekanisme pencatatan baru dengan verifikasi adalah solusinya."},
{id:"TKP-1583", q:"Seorang ibu rumah tangga ingin namanya dicantumkan sebagai kepala keluarga di KK karena suaminya pergi tanpa kabar. Petugas ragu. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan ketentuan dan membantu proses perubahan kepala keluarga sesuai fakta dengan dokumen pendukung", s:5},{t:"Menolak karena kepala keluarga harus suami", s:4},{t:"Mengubah tanpa verifikasi", s:3},{t:"Menyuruhnya menunggu suami kembali", s:2},{t:"Meminta imbalan", s:1}], ex:"Fakta pengasuhan menentukan kepala keluarga; ketentuan memfasilitasi, bukan menghambat realitas."},
{id:"TKP-1584", q:"Remaja putus sekolah ingin membuat KTP-el tetapi malu karena tidak bisa membaca tulis. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melayani dengan pendampingan ramah tanpa mempermalukan, sekaligus menginformasikan program keaksaraan", s:5},{t:"Menolak karena tidak bisa membaca", s:4},{t:"Mempermalukannya", s:3},{t:"Menyuruhnya sekolah dulu", s:2},{t:"Meminta imbalan", s:1}], ex:"Buta huruf bukan syarat penolakan KTP; pendampingan plus info program keaksaraan memberdayakan."},
{id:"TKP-1585", q:"Warga keturunan asing yang sudah menjadi WNI merasa diperlakukan curiga saat verifikasi dokumen. Ia tersinggung. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Meminta maaf, menjelaskan verifikasi berlaku untuk semua, dan melayaninya profesional setara", s:5},{t:"Membela kecurigaan petugas", s:4},{t:"Mempersulit verifikasinya", s:3},{t:"Menolak melayani", s:2},{t:"Menghinanya", s:1}], ex:"Verifikasi nondiskriminatif dijelaskan baik-baik; WNI keturunan asing setara di hadapan layanan."},
{id:"TKP-1586", q:"Seorang warga dengan HIV meminta kerahasiaan statusnya saat mengurus dokumen dan takut datanya tersebar. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjamin kerahasiaan, memproses sesuai kebutuhan dokumen saja, dan tidak mencatat/menyebarkan status kesehatannya", s:5},{t:"Menanyakan detail penyakitnya", s:4},{t:"Menyebarkan statusnya ke rekan", s:3},{t:"Menolak melayani", s:2},{t:"Menghindarinya", s:1}], ex:"Status kesehatan bukan urusan adminduk; kerahasiaan mutlak dan pelayanan tanpa stigma."},
{id:"TKP-1587", q:"Keluarga miskin ingin memakamkan jenazah tetapi terkendala akta kematian untuk administrasi pemakaman. Mereka tidak punya biaya. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mempercepat penerbitan akta kematian tanpa biaya dengan empati dan koordinasi pihak terkait", s:5},{t:"Memproses sesuai prosedur normal dengan tenggang waktu standar", s:4},{t:"Menunda penerbitan sampai keluarga mampu membayar biaya administrasi", s:3},{t:"Menolak memproses karena keluarga tidak membawa surat keterangan dari rumah sakit", s:2},{t:"Meminta bayaran tambahan agar akta kematian bisa segera diterbitkan", s:1}], ex:"Kedukaan plus kemiskinan menuntut respons cepat dan gratis; kemanusiaan di atas prosedur kaku."},
{id:"TKP-1588", q:"Warga daerah perbatasan memiliki dokumen dari dua negara dan bingung menentukan kewarganegaraan. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan ketentuan kewarganegaraan Indonesia, membantu memilih status yang sah, dan memproses sesuai pilihan legalnya", s:5},{t:"Memaksanya memilih Indonesia", s:4},{t:"Menolak karena rumit", s:3},{t:"Membiarkan kewarganegaraan ganda ilegal", s:2},{t:"Meminta imbalan", s:1}], ex:"Warga perbatasan butuh penjelasan jernih agar statusnya legal; pemaksaan atau pembiaran sama-sama salah."},
{id:"TKP-1589", q:"Seorang mantan narapidana ingin membuat KTP-el baru setelah bebas tetapi takut dicap dan dipersulit. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melayani normal tanpa stigma dan menjaga kerahasiaan masa lalunya", s:5},{t:"Mempersulit sebagai hukuman tambahan", s:4},{t:"Mengumumkan masa lalunya", s:3},{t:"Menolak melayani", s:2},{t:"Memerasnya", s:1}], ex:"Mantan napi berhak reintegrasi; stigma dalam layanan publik adalah diskriminasi."},
{id:"TKP-1590", q:"Ibu dari anak berkebutuhan khusus (autisme) kesulitan saat perekaman karena anaknya tidak nyaman di keramaian. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menyediakan waktu/ruang yang lebih tenang dan melayani dengan sabar menyesuaikan kondisi anak", s:5},{t:"Menyuruhnya datang saat sepi tanpa kepastian", s:4},{t:"Memaksa anaknya mengikuti antrean normal", s:3},{t:"Menolak melayani", s:2},{t:"Mengusir karena mengganggu", s:1}], ex:"Akomodasi wajar bagi anak berkebutuhan khusus adalah kewajiban layanan inklusif."},
{id:"TKP-1591", q:"Sistem SIAK di dinas Anda down saat antrean membludak. Warga mulai emosi. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan kondisi dengan jujur, menawarkan perekaman manual sementara yang akan dientri saat sistem pulih, dan mengoordinasikan perbaikan dengan tim IT", s:5},{t:"Menyuruh warga pulang tanpa solusi", s:4},{t:"Menyalahkan tim IT di depan warga", s:3},{t:"Berpura-pura sistem normal", s:2},{t:"Memanfaatkan down untuk pungutan", s:1}], ex:"Gangguan sistem diatasi dengan transparansi, solusi manual sementara, dan koordinasi perbaikan."},
{id:"TKP-1592", q:"Beredar pesan berantai bahwa pengurusan KTP-el akan dikenakan biaya mulai bulan depan. Banyak warga panik dan menyerbu loket. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Segera mengklarifikasi lewat kanal resmi bahwa layanan adminduk gratis dan hoaks tersebut tidak benar", s:5},{t:"Membiarkan warga panik", s:4},{t:"Mengiyakan agar warga cepat mengurus", s:3},{t:"Memanfaatkan kepanikan untuk pungutan", s:2},{t:"Menyebarkan hoaks lebih lanjut", s:1}], ex:"Hoaks dilawan dengan klarifikasi resmi cepat; kepanikan warga adalah tanggung jawab komunikasi publik."},
{id:"TKP-1593", q:"Seorang warga menerima telepon mengatasnamakan Disdukcapil meminta kode OTP dan data NIK dengan dalih verifikasi hadiah. Ia bertanya kepada Anda. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menegaskan itu penipuan, Disdukcapil tidak pernah meminta OTP, dan mengajaknya melapor", s:5},{t:"Menyuruhnya mengikuti saja instruksi penelepon", s:4},{t:"Mengabaikan pertanyaannya", s:3},{t:"Meminta warga memberikan OTP-nya kepada Anda", s:2},{t:"Ikut menelepon pelaku untuk meminta bagian", s:1}], ex:"Edukasi anti-phishing melindungi warga; penegasan plus ajakan melapor memutus kejahatan."},
{id:"TKP-1594", q:"Data kependudukan di server dinas Anda terindikasi terkena ransomware. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melaporkan ke pimpinan dan tim keamanan siber, mengisolasi sistem, dan memulihkan dari backup resmi", s:5},{t:"Membayar tebusan diam-diam", s:4},{t:"Menyembunyikan kejadian", s:3},{t:"Membiarkan sistem tetap berjalan", s:2},{t:"Memanfaatkan kekacauan untuk mencuri data", s:1}], ex:"Serangan siber ditangani prosedural: isolasi, lapor, pulihkan dari backup; tebusan bukan solusi."},
{id:"TKP-1595", q:"Warga mengeluh antrean online selalu penuh dalam hitungan detik dan diduga diborong calo lewat bot. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melaporkan ke tim IT untuk penguatan sistem (captcha, verifikasi) dan membuka kuota offline yang adil", s:5},{t:"Menyalahkan warga yang tidak cepat", s:4},{t:"Membiarkan karena sistem memang begitu", s:3},{t:"Ikut menjual slot", s:2},{t:"Menutup antrean online permanen", s:1}], ex:"Celah sistem dieksploitasi calo harus diperbaiki teknis; kuota offline adil menjaga akses."},
{id:"TKP-1596", q:"Seorang warga meminta hasil pindaian dokumen kependudukannya dikirim lewat WhatsApp pribadi petugas agar cepat. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak dan menjelaskan dokumen hanya diserahkan lewat kanal resmi demi keamanan data", s:5},{t:"Mengirimkan karena kasihan", s:4},{t:"Mengirimkan dengan imbalan", s:3},{t:"Mengirimkan ke nomor yang salah", s:2},{t:"Menyebarkan dokumennya", s:1}], ex:"Dokumen kependudukan tidak boleh lewat kanal pribadi; keamanan data di atas kemudahan semu."},
{id:"TKP-1597", q:"Backup data kependudukan dinas Anda belum dilakukan berbulan-bulan. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengusulkan dan melaksanakan jadwal backup rutin serta menguji pemulihannya", s:5},{t:"Membiarkan karena belum ada masalah", s:4},{t:"Menyalahkan bagian IT", s:3},{t:"Menghapus data lama agar hemat", s:2},{t:"Menjual data backup", s:1}], ex:"Backup rutin plus uji pemulihan adalah tanggung jawab antisipatif pengelola data."},
{id:"TKP-1598", q:"Aplikasi IKD warga error dan menampilkan data orang lain. Warga panik datanya bocor. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menenangkan, mencatat laporan bug, meneruskan ke pengembang, dan memastikan datanya diamankan", s:5},{t:"Menyalahkan ponsel warga", s:4},{t:"Menyuruhnya menghapus aplikasi", s:3},{t:"Mengabaikan laporan", s:2},{t:"Menyebarkan tangkapan layarnya", s:1}], ex:"Bug yang menyangkut data pribadi ditangani serius: dokumentasi, eskalasi, dan penenangan warga."},
{id:"TKP-1599", q:"Akun media sosial palsu mengatasnamakan Disdukcapil Anda menawarkan 'jasa percepatan dokumen' berbayar. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melaporkan akun palsu, mengumumkannya sebagai penipuan di kanal resmi, dan mengajak warga melapor", s:5},{t:"Membiarkan karena bukan akun resmi", s:4},{t:"Ikut mengelola akun tersebut", s:3},{t:"Meminta bagian dari hasilnya", s:2},{t:"Membuat akun palsu tandingan", s:1}], ex:"Akun palsu dilawan aktif: lapor, umumkan, edukasi; pembiaran merugikan warga."},
{id:"TKP-1600", q:"Verifikasi NIK online untuk keperluan perbankan warga gagal karena data belum padan. Nasabah emosi kepada Anda. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memeriksa dan memperbaiki pemadanan datanya, menjelaskan prosesnya, dan berkoordinasi agar verifikasi berhasil", s:5},{t:"Menyalahkan bank", s:4},{t:"Menyuruh nasabah menunggu tanpa kepastian", s:3},{t:"Mengubah data seenaknya agar padan", s:2},{t:"Meminta bayaran", s:1}], ex:"Gagal padan diselesaikan di sumber data dengan verifikasi; koordinasi mempercepat solusi."},
{id:"TKP-1601", q:"Rekan Anda menggunakan AI untuk mengarang jawaban atas pertanyaan data warga tanpa verifikasi. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengingatkannya bahwa data kependudukan wajib berbasis sistem resmi, bukan karangan, dan melaporkan bila berlanjut", s:5},{t:"Membiarkan karena jawabannya terlihat meyakinkan", s:4},{t:"Ikut menggunakan cara yang sama", s:3},{t:"Menyebarkan jawaban karangannya", s:2},{t:"Memanfaatkannya untuk menyesatkan warga", s:1}], ex:"Data kependudukan tidak boleh dikarang teknologi; verifikasi sistem resmi adalah mutlak."},
{id:"TKP-1602", q:"Server arsip digital penuh dan rekan mengusulkan menghapus arsip akta lama. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak penghapusan sembarangan dan mengusulkan penambahan kapasitas serta retensi arsip sesuai aturan", s:5},{t:"Setuju menghapus arsip lama", s:4},{t:"Menghapus diam-diam", s:3},{t:"Membiarkan server crash", s:2},{t:"Menjual arsip digital", s:1}], ex:"Arsip akta bersifat permanen; solusi kapasitas, bukan penghapusan, sesuai aturan kearsipan."},
{id:"TKP-1603", q:"Warga lanjut usia menjadi korban penipuan 'pemutihan data' berbayar yang mengatasnamakan program Disdukcapil. Ia kehilangan uang. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mendampingi melapor ke polisi, menjelaskan tidak ada program berbayar, dan menguatkan sosialisasi anti-penipuan", s:5},{t:"Menyalahkan korban yang mudah tertipu", s:4},{t:"Mengabaikan karena di luar kantor", s:3},{t:"Meminta korban membayar untuk pendampingan", s:2},{t:"Ikut menjalankan modus serupa", s:1}], ex:"Korban penipuan didampingi melapor; edukasi publik mencegah korban berikutnya."},
{id:"TKP-1604", q:"Tanda tangan elektronik dokumen kependudukan di dinas Anda belum tersertifikasi dan dipertanyakan keabsahannya. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengusulkan sertifikasi resmi ke penyelenggara yang berwenang dan menjelaskan statusnya transparan ke publik", s:5},{t:"Tetap memakai tanpa sertifikasi", s:4},{t:"Menyembunyikan statusnya", s:3},{t:"Memalsukan sertifikat", s:2},{t:"Menghentikan layanan digital", s:1}], ex:"Keabsahan dokumen digital butuh sertifikasi resmi; transparansi status menjaga kepercayaan."},
{id:"TKP-1605", q:"Grup WhatsApp warga dipenuhi broadcast palsu tentang 'pendataan ulang KTP' yang meminta foto KTP dan KK. Warga bertanya ke dinas. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengeluarkan pernyataan resmi bahwa itu penipuan, mengimbau tidak menyebar data, dan melaporkan penyebarnya", s:5},{t:"Mengabaikan karena hanya broadcast", s:4},{t:"Mengiyakan agar warga waspada", s:3},{t:"Ikut menyebarkan broadcast", s:2},{t:"Memanfaatkan untuk mengumpulkan data", s:1}], ex:"Phishing massal dilawan dengan pernyataan resmi dan imbauan; kecepatan klarifikasi mencegah korban."},
{id:"TKP-1606", q:"Petugas lapangan kehilangan tablet berisi data perekaman warga. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melaporkan segera, mengunci akses perangkat dari jauh, dan mengaudit potensi penyalahgunaan data", s:5},{t:"Menyembunyikan kejadian", s:4},{t:"Membiarkan karena sudah terlanjur", s:3},{t:"Menyalahkan petugas di depan umum", s:2},{t:"Menjual data di tablet tersebut", s:1}], ex:"Kehilangan perangkat berisi data sensitif ditangani darurat: kunci jarak jauh, audit, dan lapor."},
{id:"TKP-1607", q:"Website layanan Disdukcapil diretas dan menampilkan konten judi online. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melaporkan ke tim keamanan, menonaktifkan sementara, memulihkan, dan mengumumkan transparan ke publik", s:5},{t:"Membiarkan sampai pulih sendiri", s:4},{t:"Menyembunyikan dari publik", s:3},{t:"Menyalahkan pengunjung situs", s:2},{t:"Memanfaatkan untuk promosi judi", s:1}], ex:"Peretasan situs layanan publik ditangani cepat dan transparan; kepercayaan publik dipertaruhkan."},
{id:"TKP-1608", q:"Warga meminta cetakan riwayat data kependudukannya untuk keperluan pribadi. Prosedurnya belum jelas di dinas Anda. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memfasilitasi sesuai hak akses data pribadi dengan verifikasi identitas dan pencatatan resmi", s:5},{t:"Menolak karena prosedur belum ada", s:4},{t:"Memberikan tanpa verifikasi", s:3},{t:"Memberikan data orang lain sekalian", s:2},{t:"Meminta bayaran", s:1}], ex:"Hak akses data pribadi difasilitasi prosedural; kekosongan SOP bukan alasan penolakan."},
{id:"TKP-1609", q:"Kamera CCTV loket mati dan ada dugaan pungli di jam tersebut. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melaporkan dugaan pungli dan meminta investigasi, serta mengusulkan perbaikan pengawasan", s:5},{t:"Menganggap tidak ada bukti", s:4},{t:"Menutupi karena CCTV mati", s:3},{t:"Ikut memungut saat CCTV mati", s:2},{t:"Merusak CCTV lain", s:1}], ex:"Dugaan pungli tetap diinvestigasi meski CCTV mati; pengawasan diperkuat agar tidak terulang."},
{id:"TKP-1610", q:"Data warga yang sudah meninggal masih aktif dan disalahgunakan untuk pinjol oleh pihak tak bertanggung jawab. Keluarga melapor. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mempercepat pemutakhiran status kematian di sistem, berkoordinasi dengan pihak terkait, dan mendampingi keluarga melapor", s:5},{t:"Menyalahkan keluarga yang lambat melapor", s:4},{t:"Membiarkan data tetap aktif", s:3},{t:"Menghapus seluruh data almarhum", s:2},{t:"Meminta bayaran untuk pemutakhiran", s:1}], ex:"Data almarhum yang aktif disalahgunakan harus segera dimutakhirkan; pendampingan melindungi keluarga."},
{id:"TKP-1611", q:"Di grup WhatsApp pegawai, seorang rekan menyebarkan konten yang mengajak mengganti ideologi negara dengan sistem khilafah. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak paham tersebut, melaporkan penyebarannya ke atasan/aparat, dan mengingatkan rekan tentang komitmen kebangsaan ASN", s:5},{t:"Membiarkan karena hak berpendapat", s:4},{t:"Ikut menyebarkan", s:3},{t:"Mendukung ajakan tersebut", s:2},{t:"Keluar grup tanpa berbuat apa-apa", s:1}], ex:"ASN wajib setia pada Pancasila; penyebaran paham anti-ideologi negara wajib dilaporkan."},
{id:"TKP-1612", q:"Seorang warga menolak dilayani petugas yang berbeda agama dengannya dengan alasan keyakinan. Ia membuat keributan di loket. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan dengan tegas namun sopan bahwa layanan publik tidak membedakan agama, dan tetap melayaninya profesional", s:5},{t:"Mengganti petugas sesuai permintaannya", s:4},{t:"Mengusir warga tersebut", s:3},{t:"Membiarkan keributan", s:2},{t:"Ikut menyalahkan petugas", s:1}], ex:"Diskriminasi berbasis agama tidak bisa dituruti; ketegasan sopan menegakkan netralitas layanan."},
{id:"TKP-1613", q:"Rekan kerja Anda kerap menyampaikan ceramah bernada intoleran di sela jam kerja dan mengajak rekan lain. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menasihati dan melaporkannya ke atasan karena mengganggu netralitas dan kerukunan di lingkungan kerja", s:5},{t:"Membiarkan karena urusan keyakinan pribadi", s:4},{t:"Ikut menghadiri ceramahnya", s:3},{t:"Menyebarkan ceramahnya", s:2},{t:"Ikut mengajak rekan lain", s:1}], ex:"Intoleransi di lingkungan kerja ASN merusak netralitas; dinasihati lalu dilaporkan prosedural."},
{id:"TKP-1614", q:"Beredar ujaran kebencian terhadap suku tertentu di media sosial yang dikaitkan dengan layanan di dinas Anda. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengklarifikasi resmi bahwa layanan tidak diskriminatif, melaporkan ujaran kebencian, dan memperkuat standar adil", s:5},{t:"Membiarkan isu berkembang", s:4},{t:"Ikut menyebarkan ujaran tersebut", s:3},{t:"Menyalahkan suku yang dibicarakan", s:2},{t:"Menutup layanan untuk suku tersebut", s:1}], ex:"Ujaran kebencian dilawan dengan klarifikasi resmi dan penegakan layanan adil tanpa kecuali."},
{id:"TKP-1615", q:"Seorang oknum mengajak pegawai untuk tidak menghormati upacara bendera dengan alasan ideologi tertentu. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak ajakan, tetap mengikuti upacara sebagai wujud nasionalisme ASN, dan melaporkan oknum tersebut", s:5},{t:"Mengikuti ajakan tersebut", s:4},{t:"Bolos upacara diam-diam", s:3},{t:"Mengajak pegawai lain ikut menolak upacara", s:2},{t:"Menyebarkan ajakan tersebut", s:1}], ex:"Upacara bendera adalah kewajiban nasionalisme ASN; ajakan menolaknya adalah benih radikalisme."},
{id:"TKP-1616", q:"Warga pendatang dari daerah berbeda ditolak warga setempat mengurus domisili dengan alasan 'bukan orang sini'. Mereka meminta bantuan dinas. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memfasilitasi pengurusan domisilinya sesuai hak sebagai WNI dan berdialog dengan warga setempat", s:5},{t:"Menolak karena warga setempat keberatan", s:4},{t:"Menyuruh pendatang kembali ke daerah asal", s:3},{t:"Membiarkan penolakan", s:2},{t:"Memihak warga setempat", s:1}], ex:"Hak berdomisili dijamin konstitusi; dinas memfasilitasi dan mendialogkan, bukan tunduk pada eksklusivisme."},
{id:"TKP-1617", q:"Di lingkungan kantor ditemukan selebaran yang memprovokasi kebencian terhadap pemerintah yang sah. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melaporkan temuan ke atasan/aparat dan mengingatkan rekan untuk tidak terprovokasi", s:5},{t:"Membaca lalu membuangnya", s:4},{t:"Menyebarkannya ke grup", s:3},{t:"Mendukung isinya", s:2},{t:"Menempelkannya lebih banyak", s:1}], ex:"Provokasi anti-pemerintah yang sah di lingkungan ASN wajib dilaporkan; kewaspadaan kolektif dibangun."},
{id:"TKP-1618", q:"Seorang rekan terang-terangan menyatakan tidak mengakui Pancasila di depan warga yang dilayani. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menegur dan melaporkannya karena pernyataan tersebut merusak marwah ASN dan kepercayaan publik", s:5},{t:"Membiarkan karena pendapat pribadi", s:4},{t:"Mendukung pernyataannya", s:3},{t:"Ikut menyatakannya", s:2},{t:"Menyebarkannya ke media", s:1}], ex:"Penolakan terbuka terhadap Pancasila oleh ASN adalah pelanggaran berat yang wajib dilaporkan."},
{id:"TKP-1619", q:"Kelompok tertentu menekan dinas agar menolak melayani warga penganut kepercayaan lokal. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak tekanan dan tetap melayani semua warga sesuai hak konstitusionalnya", s:5},{t:"Menuruti tekanan kelompok tersebut", s:4},{t:"Menunda layanan penganut kepercayaan lokal", s:3},{t:"Ikut menekan warga tersebut", s:2},{t:"Membocorkan data mereka ke kelompok penekan", s:1}], ex:"Tekanan kelompok intoleran tidak boleh mengalahkan hak konstitusional warga; dinas berdiri netral."},
{id:"TKP-1620", q:"Anda diajak bergabung ke organisasi terlarang yang menyusup lewat kegiatan sosial pegawai. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menolak tegas dan melaporkan ajakan tersebut ke atasan/aparat", s:5},{t:"Menolak tetapi tidak melaporkan", s:4},{t:"Ikut bergabung karena penasaran", s:3},{t:"Ikut dan mengajak rekan lain", s:2},{t:"Menjadi pengurusnya", s:1}], ex:"Ajakan organisasi terlarang ditolak dan dilaporkan; kewaspadaan melindungi institusi dan diri sendiri."},
];
